"setF('${c.id}','stilAbordare',this.value)\">${[\"\",\"Formal\",\"Relațional\",\"Direct/date\",\"CSR/impact\"].map(o=>`<option ${c.stilAbordare===o?\"selected\":\"\"}>${o||\"—\"}</option>`).join(\"\")}</select></div>\r\n       <div class=\"kv col\"><label>Caz asociat</label>\r\n         <div style=\"display:flex;flex-wrap:wrap;gap:6px;margin:4px 0\">${casesList().map(cz=>`<label style=\"display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:8px;padding:4px 9px;font-size:12px;cursor:pointer\"><input type=\"checkbox\" class=\"cazPick-${c.id}\" value=\"${esc(cz)}\" ${c.cazAsociat===cz?'checked':''} onclick=\"document.querySelectorAll('.cazPick-${c.id}').forEach(x=>{if(x!==this)x.checked=false})\"> ${esc(cz)}</label>`).join(\"\")||'<span class=\"loc\">Niciun caz definit încă — scrie unul mai jos.</span>'}</div>\r\n         <div style=\"display:flex;gap:6px\"><input id=\"cazNouInp-${c.id}\" value=\"${esc(c.cazAsociat||'')}\" placeholder=\"caz nou (ex. Maria, 6 ani)\" style=\"flex:1;border:1px solid var(--line);border-radius:8px;padding:6px 9px;font-size:12.5px\"><button class=\"minibtn\" onclick=\"identificaCaz('${c.id}')\">✓ Identifică din bifă</button></div>\r\n       </div>\r\n   </div>\r\n\r\n\r\n   <div class=\"grid2\">\r\n     <div class=\"card\"><h3>Notițe — update-uri</h3><div style=\"display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap\"><input id=\"notaNou\" onkeydown=\"if(event.key==='Enter')addNota('${c.id}')\" placeholder=\"Scrie un update…\" style=\"flex:1;min-width:180px;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit\"><input id=\"notaZi\" type=\"date\" title=\"Opțional: pune notița pe o zi din calendar (gol = azi)\" style=\"border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit;color:var(--muted)\"><button class=\"linkbtn\" onclick=\"addNota('${c.id}')\">+ Notiță</button></div><div class=\"hint\" style=\"margin:-6px 0 10px\">Notița apare și pe <b>Calendar</b> la data aleasă (sau azi).</div>${notiteFeed(c)}</div>\r\n     <div class=\"card\" style=\"border:2px solid #0a7a52\"><h3>Istoric activitate <button class=\"minibtn\" onclick=\"addAct('${c.id}')\">+ activitate</button></h3>\r\n       ${renderActivitati(c)}\r\n     </div>\r\n   </div>\r\n\r\n   <div class=\"grid2\">\r\n     <div class=\"card\"><h3>✉ Email rapid</h3>\r\n       ${c.contacte.filter(p=>p.email).length?c.contacte.filter(p=>p.email).map(p=>{const ci=c.contacte.indexOf(p);return `<div class=\"rowline\"><span style=\"flex:1\">${esc(p.nume)} <span class=\"loc\">${esc(p.email)}</span></span><button class=\"minibtn\" onclick=\"openMsg('${c.id}',${ci},'email')\">Compune</button></div>`}).join(\"\"):'<div class=\"loc\">Niciun contact cu email — adaugă unul mai sus.</div>'}\r\n     </div>\r\n     <div class=\"card\"><h3>📧 Istoric emailuri</h3>\r\n       ${(c.activitati||[]).filter(a=>a.tip===\"email\").length?(c.activitati||[]).filter(a=>a.tip===\"email\").slice().reverse().map(a=>`<div class=\"rowline\" style=\"flex-direction:column;align-items:flex-start;gap:2px;padding:8px 0;border-bottom:1px solid var(--line)\"><div style=\"width:100%\">${esc(a.text)}</div>${openStatusHtml(a.mid)}<div class=\"tmeta\">${new Date(a.ts).toLocaleString(\"ro-RO\")}${a.de?\" · \"+esc(a.de):\"\"}</div></div>`).join(\"\"):'<div class=\"loc\">Niciun email trimis încă — trimite unul din „Email rapid\" sau cu ✍ pe un contact. Apare aici cu 🟢 deschis / 🔴 nedeschis.</div>'}\r\n     </div>\r\n   </div>\r\n\r\n\r\n   <div class=\"card\"><h3>Contract de sponsorizare</h3>\r\n       <div style=\"display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:4px\">\r\n         <label class=\"linkbtn\" style=\"cursor:pointer\">📎 Atașează (Word/PDF)<input type=\"file\" accept=\".pdf,.doc,.docx,application/pdf,application/msword\" hidden onchange=\"attachContractFile('${c.id}',this)\"></label>\r\n         <button class=\"linkbtn\" onclick=\"attachContractLink('${c.id}')\">🔗 Link (Drive) pt. fișiere mari</button>\r\n       </div>\r\n       ${(c.contracte&&c.contracte.length)?`<div style=\"margin-top:8px;display:flex;flex-direction:column;gap:6px\">${c.contracte.map((k,i)=>`<div class=\"rowline\"><span>📄 ${esc(k.name||k.descriere||'Contract')}${k.data?' · '+esc(k.data):''}</span> ${k.url?`<a class=\"minibtn\" href=\"${esc(k.url)}\" target=\"_blank\" rel=\"noopener\">🔗 Deschide</a>`:''}${k.dataUrl?`<a class=\"minibtn\" href=\"${k.dataUrl}\" download=\"${esc(k.name||'contract')}\">⬇ Descarcă</a>`:''}<button class=\"minibtn\" onclick=\"delArr('${c.id}','contracte',${i})\">✕</button></div>`).join(\"\")}</div>`:'<div class=\"loc\" style=\"margin-top:8px\">Niciun contract atașat — apasă „📎 Atașează\".</div>'}\r\n     </div>\r\n\r\n   <div class=\"footnote\"><b>Surse:</b> financiar din bilanțul ANAF/mfinante · contacte + LinkedIn din Lusha · administrator din Reg. Comerțului · media/istoric din research (Make). „Stil de abordare” = semnale publice, profesionale (nu profilare psihologică). Date de contact folosite pentru comunicare B2B (interes legitim), cu dezabonare.</div>`;\r\n  if(has3)renderFinChart(c.id);if(hasQ)renderQChart(c.id);\r\n}\r\n\r\n/* ============ ACȚIUNI ============ */\r\nfunction select(id){selectedId=id;recordAccess(id);document.body.classList.add(\"showing-detail\");renderList();document.querySelector(\".detail-pane\").scrollTop=0}\r\n// Glisare stânga/dreapta pe fișa firmei (mobil) → treci la compania următoare/anterioară din listă.\r\nfunction swipeCompany(dir){var ord=window._listOrder||[];if(!ord.length)return;var i=ord.indexOf(selectedId);if(i<0)i=0;var j=i+dir;if(j<0){toast(\"Prima companie din listă.\");return;}if(j>=ord.length){toast(\"Ultima companie din listă.\");return;}select(ord[j]);}\r\nfunction initSwipe(){var el=document.querySelector(\".detail-pane\");if(!el||el._swipeInit)return;el._swipeInit=true;var sx=0,sy=0,tr=false;\r\n  el.addEventListener(\"touchstart\",function(e){if(!e.touches||e.touches.length!==1)return;sx=e.touches[0].clientX;sy=e.touches[0].clientY;tr=true;},{passive:true});\r\n  el.addEventListener(\"touchend\",function(e){if(!tr)return;tr=false;var t=e.changedTouches&&e.changedTouches[0];if(!t)return;var dx=t.clientX-sx,dy=t.clientY-sy;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.7)swipeCompany(dx<0?1:-1);},{passive:true});}\r\nfunction casesList(){return [...new Set(data.map(c=>c.cazAsociat).filter(x=>x&&(\"\"+x).trim()))].sort((a,b)=>a.localeCompare(b,\"ro\"))}\r\nfunction identificaCaz(id){const c=data.find(x=>x.id===id);if(!c)return;const bifat=document.querySelector(\".cazPick-\"+id+\":checked\");const nou=(document.getElementById(\"cazNouInp-\"+id).value||\"\").trim();const val=nou||(bifat?bifat.value:\"\");if(!val){toast(\"Bifează un caz sau scrie unul nou.\");return}setF(id,\"cazAsociat\",val);toast(\"Caz identificat: \"+val)}\r\nfunction setF(id,f,v){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;c[f]=v;if(['ca','profit','impozit'].includes(f))recompSuma(c);pushCompany(c);renderList();if(selectedId===id)renderDetail()}\r\nfunction recompSuma(c){if(c.ca==null){return}let imp=c.impozit;if(imp==null&&c.profit!=null)imp=Math.round(c.profit*0.16);if(imp==null){c.suma=Math.round(c.ca*0.0075);c.sumaEst=true;return}c.suma=Math.max(0,Math.min(Math.round(c.ca*0.0075),Math.round(imp*0.2)));c.sumaEst=false;if(!(c.sursaFin&&/bilan/i.test(c.sursaFin)))c.sursaFin=\"recalculat\"}\r\nfunction setSuma(id,v){if(!canEdit())return;const c=data.find(x=>x.id===id);c.suma=v?+v:null;if(c.suma!=null)c.sumaEst=false;pushCompany(c);renderList();if(selectedId===id)renderDetail()}\r\n/* D177 și 20% sunt mecanisme fiscale EXCLUSIVE (impozit pe profit vs microîntreprindere) —\r\n   bifarea uneia o scoate automat pe cealaltă. Filtrele „prin D177\"/„prin 20%\" rămân ambele. */\r\nfunction setFiscal(id,which,on){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;if(which==='d177'){c.d177=on;if(on)c.mec20=false;}else{c.mec20=on;if(on)c.d177=false;}pushCompany(c);renderList();if(selectedId===id)renderDetail();}\r\n/* Formularul „+ Adaugă contract\": D177/20% exclusive și la bifat (bifezi una, o debifează pe cealaltă). */\r\nfunction ctFiscalDraft(fid,which,checked){saveDraftField(fid,'ctTag_'+which,checked?'1':'0');if(checked){var other=which==='d177'?'mec20':'d177';var el=document.getElementById('ctTag_'+other);if(el)el.checked=false;saveDraftField(fid,'ctTag_'+other,'0');}}\r\nfunction toggleTag(id,f,val){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;if(val!==undefined)c[f]=(c[f]===val?\"\":val);else c[f]=!c[f];if(f==='d177'&&c.d177)c.mec20=false;if(f==='mec20'&&c.mec20)c.d177=false;pushCompany(c);renderList();if(selectedId===id)renderDetail()}\r\nfunction addContract(id){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;const descriere=prompt(\"Descriere contract (ex. Sponsorizare 2026):\");if(!descriere)return;const suma=+prompt(\"Sumă (lei)? (opțional)\")||0;const dt=prompt(\"Dată (ex. 2026-03-01)? (opțional)\")||\"\";const status=prompt(\"Status (trimis / semnat / în derulare)? (opțional)\")||\"\";c.contracte=c.contracte||[];c.contracte.push({descriere,suma,data:dt,status,name:null,dataUrl:null,ts:Date.now()});logAct(c,\"status\",\"Contract adăugat: \"+descriere);pushCompany(c);renderDetail();toast(\"Contract adăugat.\")}\r\nfunction attachContractFile(id,inp){const f=inp.files[0];if(!f){return}if(f.size>700*1024){toast(\"Fișier prea mare (max ~0,7MB). Comprimă PDF-ul sau folosește butonul de Link Drive.\");inp.value=\"\";return}const r=new FileReader();r.onload=()=>{const c=data.find(x=>x.id===id);if(!c)return;c.contracte=c.contracte||[];c.contracte.push({name:f.name,dataUrl:r.result,data:new Date().toISOString().slice(0,10),ts:Date.now()});logAct(c,\"status\",\"Contract atașat: \"+f.name);pushCompany(c);renderDetail();toast(\"Contract atașat: \"+f.name)};r.readAsDataURL(f);inp.value=\"\"}\r\nfunction attachContractLink(id){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;const url=prompt(\"Lipește linkul contractului (Google Drive / Dropbox / etc.):\");if(!url)return;const name=prompt(\"Nume/etichetă (ex. Contract sponsorizare 2026):\")||\"Contract\";c.contracte=c.contracte||[];c.contracte.push({name,url:url.trim(),data:new Date().toISOString().slice(0,10),ts:Date.now()});logAct(c,\"status\",\"Contract (link) adăugat: \"+name);pushCompany(c);renderDetail();toast(\"Link contract adăugat.\")}\r\nfunction attachContract(id,i,inp){const f=inp.files[0];if(!f)return;if(f.size>700*1024){toast(\"Max ~0,7MB — folosește link pentru fișiere mari.\");return}const r=new FileReader();r.onload=()=>{const c=data.find(x=>x.id===id);if(!c||!c.contracte||!c.contracte[i])return;c.contracte[i].name=f.name;c.contracte[i].dataUrl=r.result;pushCompany(c);renderDetail();toast(\"Fișier atașat.\")};r.readAsDataURL(f)}\r\nlet contractForId=null,contractTip=\"d177\";\r\nfunction openContract(id){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;contractForId=id;const sediu=[c.localitate,c.adresa].filter(x=>x&&(\"\"+x).trim()).join(\", \");const set=(k,val)=>{const e=document.getElementById(k);if(e)e.value=val==null?\"\":val};set(\"ct_nume\",tc(c.nume));set(\"ct_sediu\",sediu);set(\"ct_judet\",c.judet);set(\"ct_cui\",c.cui);set(\"ct_reg\",c.nrRegCom);set(\"ct_rep\",c.administrator);set(\"ct_fct\",\"Administrator\");set(\"ct_iban\",\"\");set(\"ct_banca\",\"\");set(\"ct_suma\",c.sumaPropusa||c.suma||\"\");set(\"ct_nr\",\"\");set(\"ct_data\",\"\");set(\"ct_caz\",c.cazAsociat);set(\"ct_resp\",c.responsabil);setCtTip(\"d177\");document.getElementById(\"contractOverlay\").classList.add(\"on\")}\r\nfunction setCtTip(t){contractTip=t;const a=document.getElementById(\"ctBtnD177\"),b=document.getElementById(\"ctBtn20\");if(a)a.classList.toggle(\"primary\",t===\"d177\");if(b)b.classList.toggle(\"primary\",t===\"mec20\")}\r\nfunction genContract(mode){const c=data.find(x=>x.id===contractForId);const gv=k=>{const e=document.getElementById(k);return e?e.value.trim():\"\"};const v={nume:gv(\"ct_nume\"),sediu:gv(\"ct_sediu\"),judet:gv(\"ct_judet\"),cui:gv(\"ct_cui\"),reg:gv(\"ct_reg\"),rep:gv(\"ct_rep\"),fct:gv(\"ct_fct\")||\"Administrator\",iban:gv(\"ct_iban\"),banca:gv(\"ct_banca\"),suma:gv(\"ct_suma\"),nr:gv(\"ct_nr\"),data:gv(\"ct_data\"),caz:gv(\"ct_caz\"),resp:gv(\"ct_resp\")};const html=buildContract(v,contractTip);if(mode===\"pdf\"){const w=window.open(\"\",\"_blank\");if(!w){toast(\"Permite pop-up-urile pentru a genera PDF.\");return}w.document.write(html+\"<scr\"+\"ipt>window.onload=function(){setTimeout(function(){window.print()},250)}<\\/scr\"+\"ipt>\");w.document.close()}else{const blob=new Blob([\"\\ufeff\"+html],{type:\"application/msword\"});const url=URL.createObjectURL(blob);const a=document.createElement(\"a\");a.href=url;a.download=\"Contract_\"+(contractTip===\"d177\"?\"D177\":\"20la-suta\")+\"_\"+((v.nume||\"firma\").replace(/[^a-zA-Z0-9]+/g,\"_\").slice(0,40))+\".doc\";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}if(c){logAct(c,\"status\",\"Contract generat (\"+(contractTip===\"d177\"?\"D177\":\"20%\")+\")\");pushCompany(c)}closeOv(\"contractOverlay\");toast(mode===\"pdf\"?\"Deschis pentru print → salvează ca PDF.\":\"Contract descărcat (Word).\")}\r\nfunction d177Deadline(){const y=new Date().getFullYear();const d=new Date(y,5,25);return d<new Date()?(\"25.06.\"+(y+1)):(\"25.06.\"+y);}\r\nfunction buildContract(v,tip){\r\n const g=x=>(x!=null&&(\"\"+x).trim())?esc(\"\"+x):\"____\";\r\n const og=k=>g(config[k]);\r\n const gsuma=x=>{const n=(\"\"+(x==null?\"\":x)).replace(/[^\\d]/g,\"\");return n?Number(n).toLocaleString(\"ro-RO\"):\"____\";};\r\n const sediu=(v.judet&&(\"\"+v.judet).trim())?(g(v.sediu)+\", jud. \"+g(v.judet)):g(v.sediu);\r\n const dt=(v.data&&/^\\d{4}-\\d{2}-\\d{2}$/.test(v.data))?v.data.split(\"-\").reverse().join(\".\"):g(v.data);\r\n const foot=`<p style=\"font-size:9pt;color:#666;margin-top:22px\">Format: ${tip===\"d177\"?\"D177 — redirecţionare impozit pe profit\":\"20% — sponsorizare directă\"}${(v.caz&&v.caz.trim())?\" · Caz asociat: \"+g(v.caz):\"\"}${(v.resp&&v.resp.trim())?\" · Responsabil: \"+g(v.resp):\"\"}</p>`;\r\n const H=`<div style=\"text-align:center;margin-bottom:18px\"><div style=\"font-size:16pt;font-weight:bold;letter-spacing:1px\">CONTRACT DE SPONSORIZARE</div>${tip===\"d177\"?`<div style=\"font-size:11pt;margin-top:4px\">Nr. ${g(v.nr)} / ${dt}</div>`:``}</div>`;\r\n const semn=`<table style=\"width:100%;margin-top:34px\"><tr><td style=\"text-align:center;width:50%;vertical-align:top\">SPONSOR<br><br><br>${g(v.nume)}<br>${g(v.rep)}<br>${g(v.fct)}</td><td style=\"text-align:center;width:50%;vertical-align:top\">BENEFICIAR<br><br><br>${g(config.ongNume)}<br>${g(config.ongReprezentant)}<br>${g(config.ongFunctie)}</td></tr></table>`;\r\n let b;\r\n if(tip===\"d177\"){\r\n  b=`<p><b>I. PĂRŢILE CONTRACTANTE</b></p>\r\n<p><b>1.1.</b> ${g(v.nume)}, cu sediul în ${sediu}, C.I.F. ${g(v.cui)}, înregistrată la Oficiul Registrului Comerţului sub nr. ${g(v.reg)}, având contul IBAN ${g(v.iban)}, deschis la Banca ${g(v.banca)}, reprezentată de ${g(v.rep)}, cu funcţia de ${g(v.fct)}, în calitate de <b>Sponsor</b>, pe de o parte,</p>\r\n<p>şi</p>\r\n<p><b>1.2.</b> ${og(\"ongNume\")}, cu sediul social în ${og(\"ongSediu\")}, cod de identificare fiscală ${og(\"ongCif\")}, cu contul în lei ${og(\"ongIban\")}, deschis la ${og(\"ongBanca\")}${config.ongInregistrare?\", \"+g(config.ongInregistrare):\"\"}, reprezentată legal la data semnării de către ${og(\"ongReprezentant\")}, ${og(\"ongFunctie\")}, în calitate de <b>Beneficiar</b> al sponsorizării, pe de altă parte, au convenit să încheie prezentul contract de sponsorizare, cu respectarea următoarelor clauze:</p>\r\n<p><b>II. OBIECTUL CONTRACTULUI</b></p>\r\n<p><b>2.1.</b> În vederea sprijinirii generale a activităţilor desfăşurate de ${og(\"ongNume\")}. Sponsorul pune la dispoziţia Beneficiarului, în condiţiile Ordinului 1679/2022, prin Declaraţia 177 cu modificările aduse prin OG 115/2023 şi la termenele prevăzute de aceasta, o sponsorizare în bani în valoare de <b>${gsuma(v.suma)} RON</b>.</p>\r\n<p><b>III. OBLIGAŢIILE PĂRŢILOR</b></p>\r\n<p><b>3.1.</b> Suma aferentă sponsorizării va fi direcţionată de către ANAF în contul Beneficiarului: ${og(\"ongIban\")}, deschis la ${og(\"ongBanca\")}. Pentru ca ANAF să poată efectua transferul, Sponsorul are obligaţia de a completa şi depune Declaraţia Fiscală 177 până la data de ${d177Deadline()}.</p>\r\n<p><b>3.2.</b> Beneficiarul va informa publicul despre contribuţia sponsorului prin menţionarea numelui acestuia şi a valorii sponsorizate${config.ongSite?\" pe \"+og(\"ongSite\"):\"\"}.</p>\r\n<p><b>3.3.</b> Orice acţiune de comunicare publică, inclusiv anunţarea sponsorizării pe site-ul propriu sau prin alte canale media, va conţine denumirea proiectului şi informaţii relevante despre Beneficiar. În acest context, Sponsorul se angajează să colaboreze cu Beneficiarul pentru aprobarea în prealabil a conţinutului materialelor de promovare şi a canalelor de distribuţie utilizate.</p>\r\n<p><b>3.4.</b> ${og(\"ongNume\")} îşi desfăşoară activitatea transparent, utilizând sumele primite exclusiv în scopul pentru care au fost destinate. Beneficiarul se obligă să informeze periodic Sponsorul cu privire la folosirea fondurilor, acesta având dreptul să verifice dacă sponsorizarea a fost utilizată conform obiectivelor proiectului.</p>\r\n<p><b>3.5.</b> Sponsorul se angajează să nu influenţeze, direct sau indirect, activitatea Beneficiarului, respectând independenţa acestuia în gestionarea proiectelor umanitare.</p>\r\n<p><b>3.6.</b> Sponsorizarea va fi comunicată public într-un mod care să protejeze reputaţia proiectului susţinut, respectând valorile morale şi evitând orice prejudiciu de imagine.</p>\r\n<p><b>3.7.</b> Beneficiarul va prezenta Sponsorului un raport de activitate detaliat cel puţin o dată pe an, pentru a asigura transparenţa şi încrederea între părţi.</p>\r\n<p><b>IV. DURATA CONTRACTULUI</b></p>\r\n<p><b>4.1.</b> Prezentul contract de sponsorizare intră în vigoare la data semnării şi îşi menţine valabilitatea până la finalizarea proiectului umanitar pentru care a fost încheiat.</p>\r\n<p><b>V. ÎNCETAREA CONTRACTULUI</b></p>\r\n<p><b>5.1.</b> Contractul încetează automat, fără intervenţia instanţelor, dacă una dintre părţi nu respectă o obligaţie esenţială, este declarată insolventă, cesionează drepturile fără acord, sau continuă să încalce obligaţiile în ciuda unui avertisment oficial.</p>\r\n<p><b>5.2.</b> Rezilierea contractului nu afectează obligaţiile deja asumate şi scadente între părţi.</p>\r\n<p><b>VI. FORŢA MAJORĂ</b></p>\r\n<p><b>6.1.</b> Niciuna dintre părţi nu poate fi considerată responsabilă pentru neexecutarea obligaţiilor, dacă aceasta este cauzată de un eveniment de forţă majoră, conform legislaţiei aplicabile. Partea care invocă forţa majoră va notifica cealaltă parte în termen de 3 zile.</p>\r\n<p><b>VII. LITIGII</b></p>\r\n<p><b>7.1.</b> Orice neînţelegeri vor fi soluţionate prin negocieri directe; dacă nu se ajunge la o înţelegere amiabilă, litigiile vor fi soluţionate de către instanţele competente.</p>\r\n<p><b>VIII. CLAUZE FINALE</b></p>\r\n<p><b>8.1.</b> Orice modificare se poate face doar printr-un act adiţional semnat de ambele părţi. Contractul reflectă în totalitate acordul părţilor.</p>${semn}`;\r\n } else {\r\n  b=`<p><b>I. PĂRŢILE CONTRACTANTE</b></p>\r\n<p><b>1.1.</b> ${g(v.nume)}, cu sediul social în ${sediu}, cu contul bancar ${g(v.iban)}, deschis la ${g(v.banca)}, înregistrată la Oficiul Registrului Comerţului sub nr. ${g(v.reg)}, cod unic de înregistrare ${g(v.cui)}, reprezentată legal la data semnării prezentului contract de ${g(v.rep)}, având funcţia de ${g(v.fct)}, în calitate de <b>SPONSOR</b>,</p>\r\n<p>şi</p>\r\n<p><b>2.1.</b> ${og(\"ongNume\")}, cu sediul social în ${og(\"ongSediu\")}, Cod de identificare fiscală ${og(\"ongCif\")}, cu contul în lei ${og(\"ongIban\")}, deschis la ${og(\"ongBanca\")}, reprezentată legal la data semnării de către ${og(\"ongReprezentant\")} — ${og(\"ongFunctie\")}, în calitate de <b>BENEFICIAR AL SPONSORIZĂRII</b>. Au convenit să încheie prezentul contract în conformitate cu prevederile Legii nr. 32/1994 privind sponsorizarea, Legii nr. 227/2015 (Codul Fiscal), Legii nr. 287/2009 (Codul Civil) şi ale Regulamentului (UE) 2016/679 (GDPR).</p>\r\n<p><b>II. OBIECTUL CONTRACTULUI</b></p>\r\n<p><b>2.1.</b> Obiectul prezentului contract îl constituie sponsorizarea Beneficiarului de către Sponsor în vederea strângerii de fonduri pentru susţinerea activităţilor derulate de ${og(\"ongNume\")}.</p>\r\n<p><b>2.2.</b> În scopul prevăzut la pct. 2.1, Sponsorul se angajează să pună la dispoziţia beneficiarului suma de <b>${gsuma(v.suma)} RON</b>.</p>\r\n<p><b>III. DURATA CONTRACTULUI</b></p>\r\n<p><b>3.1.</b> Prezentul contract intră în vigoare la data semnării sale de către părţile contractante şi este valabil până la îndeplinirea obligaţiilor de către ambele părţi.</p>\r\n<p><b>IV. PREŢUL CONTRACTULUI ŞI MODALITATEA DE PLATĂ</b></p>\r\n<p><b>4.1.</b> Sponsorul va acorda Beneficiarului suma de <b>${gsuma(v.suma)} RON</b>.</p>\r\n<p><b>4.2.</b> Plata se face în Lei, în contul ${og(\"ongNume\")}. Sponsorizarea este unică.</p>\r\n<p><b>V. OBLIGAŢIILE BENEFICIARULUI</b></p>\r\n<p><b>5.1.</b> Beneficiarul se obligă să folosească sumele acordate exclusiv în scopul precizat la art. 2.1. <b>5.2.</b> La solicitarea Sponsorului, Beneficiarul se obligă să informeze despre modul în care au fost utilizate fondurile şi să pună la dispoziţie documente justificative. <b>5.3.</b> Beneficiarul poate aduce la cunoştinţa publicului sponsorizarea prin promovarea numelui, mărcii sau imaginii sponsorului (conform art. 5 din Legea nr. 32/1994). <b>5.4.</b> Beneficiarul va prezenta Sponsorului spre aprobare materialele în care vor fi utilizate însemnele sale.</p>\r\n<p><b>VI. OBLIGAŢIILE SPONSORULUI</b></p>\r\n<p><b>6.1.</b> Sponsorul se obligă să vireze suma precizată la art. 4.1. în contul Beneficiarului, în termen de 30 zile de la semnarea contractului. <b>6.2.</b> Sponsorul poate aduce la cunoştinţa publicului sponsorizarea prin modalităţile pe care le consideră adecvate. <b>6.3.</b> Sponsorul va trimite spre aprobare Beneficiarului, înainte de publicare, materialele care încorporează numele sau sigla Beneficiarului.</p>\r\n<p><b>VII. CESIUNEA CONTRACTULUI</b></p>\r\n<p><b>7.1.</b> Niciuna din părţi nu va cesiona drepturile şi obligaţiile rezultate din acest contract unei terţe persoane.</p>\r\n<p><b>VIII. NOTIFICĂRI</b></p>\r\n<p><b>8.1.</b> Orice notificare adresată de una dintre părţi celeilalte este valabil îndeplinită dacă va fi transmisă la adresa/sediul prevăzut în capitolul I, prin scrisoare recomandată cu confirmare de primire.</p>\r\n<p><b>IX. CONFIDENŢIALITATE</b></p>\r\n<p><b>9.1.</b> O parte contractantă nu are dreptul, fără acordul scris al celeilalte, să facă cunoscut contractul unei terţe părţi sau să utilizeze informaţiile obţinute în alt scop decât îndeplinirea obligaţiilor contractuale.</p>\r\n<p><b>X. PROTECŢIA DATELOR CU CARACTER PERSONAL</b></p>\r\n<p><b>10.1.</b> Părţile au cunoştinţă de dispoziţiile Regulamentului GDPR şi se obligă să le respecte întocmai. Fiecare parte are calitatea de operator de date cu caracter personal. Beneficiarul se obligă să prelucreze datele personale ale reprezentanţilor Sponsorului doar în scopul derulării relaţiei contractuale şi să le şteargă/anonimizeze la solicitarea scrisă (${og(\"ongEmail\")}) sau la încetarea relaţiei, cu excepţiile legale. Obligaţiile privind datele rămân valabile pe durata contractului şi 5 ani după încetare.</p>\r\n<p><b>XI. DISPOZIŢII FINALE</b></p>\r\n<p><b>11.1.</b> Modificarea contractului poate fi făcută numai în scris, prin acordul ambelor părţi. <b>11.2.</b> Orice litigii se vor soluţiona pe cale amiabilă, iar în caz contrar de instanţele judecătoreşti competente. <b>11.3.</b> Forţa majoră exonerează de răspundere conform legii.</p>${semn}`;\r\n }\r\n return `<html xmlns:o=\"urn:schemas-microsoft-com:office:office\" xmlns:w=\"urn:schemas-microsoft-com:office:word\"><head><meta charset=\"utf-8\"><title>Contract sponsorizare</title></head><body style=\"font-family:'Times New Roman',serif;font-size:12pt;line-height:1.5;text-align:justify;color:#000;max-width:730px;margin:0 auto\">${H}${b}${foot}</body></html>`;\r\n}\r\nfunction resetData(){if(!confirm(\"Ștergi datele salvate local în acest browser și reîncarci exemplele corecte? Nu afectează ce e deja sincronizat pentru echipă.\"))return;try{localStorage.removeItem(KEY)}catch(e){}location.reload()}\r\nfunction topStage(arr){let best=-1,bk=null;(arr||[]).forEach(k=>{const i=stIdx(k);if(i>best){best=i;bk=k}});return bk}\r\nfunction toggleStage(id,k){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;\r\n  c.stagesBifate=c.stagesBifate||STAGES.filter(s=>stIdx(s.k)<=stIdx(c.status)).map(s=>s.k);\r\n  const i=c.stagesBifate.indexOf(k);if(i>-1)c.stagesBifate.splice(i,1);else c.stagesBifate.push(k);\r\n  c.status=topStage(c.stagesBifate)||\"nou\";\r\n  logAct(c,\"status\",\"→ \"+stLabel(c.status));pushCompany(c);renderList();renderDetail();toast(\"Status: \"+stLabel(c.status))}\r\nfunction setStatus(id,k){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;\r\n  if(k===\"respins\"){c.status=c.status===\"respins\"?(topStage(c.stagesBifate)||\"nou\"):\"respins\";logAct(c,\"status\",\"→ \"+stLabel(c.status));pushCompany(c);renderList();renderDetail();toast(\"Status: \"+stLabel(c.status));return}\r\n  toggleStage(id,k)}\r\nfunction setQ(id,q,v){const c=data.find(x=>x.id===id);if(!c)return;c.trimestre=c.trimestre||{};c.trimestre[q]=v?+v:0;pushCompany(c);renderQChart(id)}\r\nfunction addIstoric(id){const c=data.find(x=>x.id===id);const an=prompt(\"An?\");if(!an)return;c.istoric=c.istoric||[];c.istoric.push({an,suma:+prompt(\"Sumă (lei)?\")||0,beneficiar:prompt(\"Beneficiar (noi / alt ONG)?\")||\"noi\",modalitate:prompt(\"Modalitate (D177/20%/directă)?\")||\"\"});pushCompany(c);renderDetail()}\r\nfunction addMedia(id){const c=data.find(x=>x.id===id);const titlu=prompt(\"Titlu apariție?\");if(!titlu)return;c.media=c.media||[];c.media.push({titlu,sursa:prompt(\"Sursă?\")||\"\",an:prompt(\"An?\")||\"\",link:prompt(\"Link?\")||\"\"});pushCompany(c);renderDetail()}\r\nfunction addFin(id){const c=data.find(x=>x.id===id);const an=+prompt(\"An?\");if(!an)return;c.financiar3ani=c.financiar3ani||[];c.financiar3ani.push({an,ca:+prompt(\"Cifră afaceri (lei)?\")||0,profit:+prompt(\"Profit (lei)?\")||0});c.financiar3ani.sort((a,b)=>a.an-b.an);pushCompany(c);renderDetail()}\r\nfunction delArr(id,arr,i){const c=data.find(x=>x.id===id);c[arr].splice(i,1);pushCompany(c);renderDetail()}\r\nfunction reveal(b){b.classList.add(\"done\");b.textContent=\"⏳ Lusha\";toast(\"Se revelează în scenariul Make (consumă credite).\")}\r\nfunction setContact(id,ci,f,v){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c||!c.contacte[ci])return;c.contacte[ci][f]=v||null;pushCompany(c)}\r\n// ❤️ contact prioritar / om direct de contact (refolosim „cheie\": apare cu inimioară + primul în listă)\r\nfunction toggleCheie(id,ci){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c||!c.contacte[ci])return;c.contacte[ci].cheie=!c.contacte[ci].cheie;pushCompany(c);renderDetail();toast(c.contacte[ci].cheie?\"Marcat prioritar ❤\":\"Scos de la prioritari\");}\r\nfunction delContact(id,ci){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c.contacte[ci])return;if(!confirm(\"Ștergi contactul „\"+c.contacte[ci].nume+\"”?\"))return;c.contacte.splice(ci,1);pushCompany(c);renderDetail()}\r\nfunction delCompany(id){if(!canEdit())return;const c=data.find(x=>x.id===id);if(!c)return;if(!confirm(\"Ștergi firma „\"+tc(c.nume)+\"”?\\n\\nDispare din listă (se poate recupera din baza de date de către un administrator).\"))return;fetch(API_BASE+\"/crm-companies/\"+id,{method:\"DELETE\"}).then(r=>r.json()).then(j=>{if(j&&j.ok){data=data.filter(x=>x.id!==id);try{saveCache()}catch(e){}selectedId=null;document.body.classList.remove(\"showing-detail\");renderList();toast(\"Firmă ștearsă.\")}else toast(\"Nu s-a putut șterge (permisiuni?).\");}).catch(()=>toast(\"Conexiune eșuată.\"))}\r\nconst POZITII=[\"CEO\",\"OWNER\",\"Director economic\",\"CSR\",\"Director financiar\",\"HR\",\"Marketing\",\"Administrator\",\"Președinte\",\"Contabil\"];\r\nfunction pozDept(p){p=(p||\"\").toLowerCase();\r\n  if(/financiar|economic|contabil/.test(p))return \"Financiar\";\r\n  if(/csr/.test(p))return \"CSR\";\r\n  if(/hr/.test(p))return \"HR\";\r\n  if(/marketing/.test(p))return \"Marketing\";\r\n  if(/ceo|owner|administrator|președinte|presedinte/.test(p))return \"Conducere\";\r\n  return \"\";}\r\nlet addContactForId=null,editContactIdx=null;\r\nfunction addContact(id){openAddContact(id,null)}\r\nfunction editContact(id,idx){openAddContact(id,idx)}\r\nfunction openAddContact(id,idx){if(!canEdit())return;addContactForId=id;editContactIdx=(idx==null?null:idx);\r\n  const c=data.find(x=>x.id===id);const p=(idx!=null&&c&&c.contacte[idx])?c.contacte[idx]:null;\r\n  const sel=p?String(p.rol||\"\").split(/,\\s*/).map(s=>s.trim()):[];\r\n  document.getElementById(\"pozBox\").innerHTML=POZITII.map(pz=>`<label style=\"display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:8px;padding:5px 10px;font-size:13px;cursor:pointer\"><input type=\"checkbox\" class=\"pozChk\" value=\"${esc(pz)}\" ${sel.includes(pz)?\"checked\":\"\"}>${esc(pz)}</label>`).join(\"\");\r\n  document.getElementById(\"ctRol\").value=sel.filter(s=>!POZITII.includes(s)).join(\", \");\r\n  document.getElementById(\"ctNume\").value=p?(p.nume||\"\"):\"\";\r\n  document.getElementById(\"ctTel\").value=p?(p.telefon||\"\"):\"\";\r\n  document.getElementById(\"ctEmail\").value=p?(p.email||\"\"):\"\";\r\n  document.getElementById(\"ctFb\").value=p?(p.facebook||\"\"):\"\";\r\n  document.getElementById(\"ctLi\").value=p?(p.linkedin||\"\"):\"\";\r\n  document.getElementById(\"ctWeb\").value=(c&&c.site)||\"\";\r\n  const dt=document.getElementById(\"ctData\");if(dt)dt.value=(p&&p.dataPropunere)?p.dataPropunere:new Date().toISOString().slice(0,10);\r\n  const pr=document.getElementById(\"ctPrioritar\");if(pr)pr.checked=!!(p&&p.cheie);\r\n  const h=document.querySelector(\"#addContactOverlay h3\");if(h)h.textContent=p?\"Editează contactul\":\"Adaugă persoană de contact\";\r\n  document.getElementById(\"addContactOverlay\").classList.add(\"on\");\r\n}\r\nfunction saveNewContact(){const c=data.find(x=>x.id===addContactForId);if(!c)return;\r\n  const poz=[...document.querySelectorAll(\".pozChk:checked\")].map(x=>x.value);\r\n  const custom=(document.getElementById(\"ctRol\").value||\"\").trim();\r\n  if(custom)custom.split(/,\\s*/).forEach(f=>{if(f&&!poz.includes(f))poz.push(f)});\r\n  const emailV=(document.getElementById(\"ctEmail\").value||\"\").trim(),telV=(document.getElementById(\"ctTel\").value||\"\").trim();\r\n  let nume=(document.getElementById(\"ctNume\").value||\"\").trim();\r\n  // Poți adăuga un contact doar cu telefon sau email, fără nume — folosim email/telefon ca nume.\r\n  if(!nume){if(emailV||telV){nume=emailV||telV;}else{toast(\"Pune numele, sau măcar un email ori un telefon.\");return}}\r\n  const dept=poz.map(pozDept).find(Boolean)||\"\";\r\n  const web=(document.getElementById(\"ctWeb\").value||\"\").trim();if(web)c.site=web;\r\n  const obj={nume,rol:poz.join(\", \"),dept,\r\n    linkedin:(document.getElementById(\"ctLi\").value||\"\").trim()||null,\r\n    facebook:(document.getElementById(\"ctFb\").value||\"\").trim()||null,\r\n    email:(document.getElementById(\"ctEmail\").value||\"\").trim()||null,\r\n    telefon:(document.getElementById(\"ctTel\").value||\"\").trim()||null,\r\n    dataPropunere:(document.getElementById(\"ctData\").value||\"\")||null,\r\n    cheie:(document.getElementById(\"ctPrioritar\")&&document.getElementById(\"ctPrioritar\").checked)||[\"Conducere\",\"Financiar\",\"HR\",\"Marketing\",\"CSR\"].includes(dept)};\r\n  if(editContactIdx!=null&&c.contacte[editContactIdx]){Object.assign(c.contacte[editContactIdx],obj)}\r\n  // Consimțământ GDPR automat la contact nou: temeiul e contractul de sponsorizare semnat.\r\n  // (Serverul înregistrează consentAt/consentBy/consentSource pt audit.) Se poate schimba din click dacă e cazul.\r\n  else{obj.loc=\"\";obj.detalii=\"\";obj.consimtamant=\"acord\";obj.consentSource=\"Contract sponsorizare\";c.contacte.push(obj);logAct(c,\"contact\",\"➕ Contact adăugat: \"+nume+(poz.length?\" — \"+poz.join(\", \"):\"\"))}\r\n  Promise.resolve(pushCompany(c)).then(()=>{loadContactActivity();renderDetail();renderList();});closeOv(\"addContactOverlay\");renderDetail();toast(editContactIdx!=null?\"Contact actualizat.\":\"Contact adăugat: \"+nume);}\r\nfunction cycleConsent(id,ci){if(!canEdit())return;const c=data.find(x=>x.id===id),p=c.contacte[ci];const order=[\"?\",\"acord\",\"dezabonat\"];p.consimtamant=order[(order.indexOf(p.consimtamant||\"?\")+1)%3];pushCompany(c);renderDetail()}\r\nfunction clearFollow(id){const c=data.find(x=>x.id===id);c.followupAt=null;pushCompany(c);renderZi()}\r\nfunction setFollowup(id){if(!canEdit())return;const c=data.find(x=>x.id===id);c.followupAt=Date.now()+48*3600*1000;logAct(c,\"apel\",\"Programat revenire telefon (48h)\");pushCompany(c);\r\n  runMake(\"followup\",{companie:c.nume,cand:new Date(c.followupAt).toISOString(),responsabil:c.responsabil});\r\n  addTask({titlu:\"Sună \"+c.nume,companie:c.nume,catre:c.responsabil||config.eu,scadenta:new Date(c.followupAt).toISOString().slice(0,10)});renderDetail();toast(\"Revenire 48h + sarcină.\")}\r\nfunction addAct(id){if(!canEdit())return;const c=data.find(x=>x.id===id);const text=prompt(\"Ce s-a întâmplat? (apel, email, întâlnire, notă)\");if(!text)return;logAct(c,\"nota\",text);pushCompany(c);renderDetail()}\r\nfunction setRenewal(id){if(!canEdit())return;const c=data.find(x=>x.id===id);const baza=c.lastDonation?new Date(c.lastDonation):new Date();const d=new Date(baza);d.setFullYear(d.getFullYear()+1);c.nextAsk=d.toISOString().slice(0,10);logAct(c,\"nota\",\"Programat următorul ask: \"+c.nextAsk);pushCompany(c);addTask({titlu:\"Reînnoire \"+c.nume,companie:c.nume,catre:c.responsabil||config.eu,scadenta:c.nextAsk});renderDetail();toast(\"Reînnoire programată: \"+c.nextAsk)}\r\nfunction uploadContract(id,inp){const f=inp.files[0];if(!f)return;if(f.size>4*1024*1024){toast(\"Max 4MB.\");return}const r=new FileReader();r.onload=()=>{const c=data.find(x=>x.id===id);c.contract={name:f.name,dataUrl:r.result};pushCompany(c);renderDetail();toast(\"Contract atașat.\")};r.readAsDataURL(f)}\r\nfunction renderQChart(id){const c=data.find(x=>x.id===id),el=document.getElementById(\"qChart\");if(!el||typeof Chart===\"undefined\")return;document.getElementById(\"qWrap\").style.display=\"block\";if(chartCo)chartCo.destroy();\r\n  chartCo=new Chart(el,{type:\"bar\",data:{labels:[\"Q1\",\"Q2\",\"Q3\",\"Q4\"],datasets:[{data:[c.trimestre.q1||0,c.trimestre.q2||0,c.trimestre.q3||0,c.trimestre.q4||0],backgroundColor:\"#0E7C6B\",borderRadius:6}]},options:{plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>v.toLocaleString(\"ro-RO\")}}},maintainAspectRatio:false}})}\r\nfunction renderFinChart(id){const c=data.find(x=>x.id===id),el=document.getElementById(\"finChart\");if(!el||typeof Chart===\"undefined\"||!c.financiar3ani.length)return;if(chartFin)chartFin.destroy();\r\n  chartFin=new Chart(el,{type:\"bar\",data:{labels:c.financiar3ani.map(f=>f.an),datasets:[{label:\"Cifră afaceri\",data:c.financiar3ani.map(f=>f.ca),backgroundColor:\"#C81E4A\",borderRadius:5},{label:\"Profit\",data:c.financiar3ani.map(f=>f.profit),backgroundColor:\"#0E7C6B\",borderRadius:5}]},options:{plugins:{legend:{position:\"bottom\"}},scales:{y:{ticks:{callback:v=>(v/1e6).toLocaleString(\"ro-RO\")+\"M\"}}},maintainAspectRatio:false}})}\r\n\r\n/* ============ COMPOSER ============ */\r\nlet M={};\r\nfunction openMsg(id,ci){M={canal:\"email\",id,ci};const c=data.find(x=>x.id===id);renderMsg(c,c.contacte[ci]);document.getElementById(\"msgOverlay\").classList.add(\"on\")}\r\nfunction reRenderMsg(){const c=data.find(x=>x.id===M.id);renderMsg(c,c.contacte[M.ci])}\r\nfunction renderMsg(c,p){\r\n  document.getElementById(\"msgModal\").innerHTML=`<div style=\"display:flex;justify-content:space-between;align-items:flex-start;gap:10px\"><div><h3>Email către ${esc(p.nume)}</h3><p>${esc(p.rol)} · ${esc(c.nume)}${p.email?' · '+esc(p.email):''}</p></div><button class=\"minibtn\" onclick=\"closeOv('msgOverlay')\">✕ Închide</button></div>\r\n    <div class=\"fld\"><label>Subiect</label><input id=\"mSubj\" placeholder=\"Scrie subiectul emailului\"></div>\r\n    <textarea id=\"mBody\" placeholder=\"Scrie mesajul aici…\"></textarea>\r\n    <div class=\"row\"><button class=\"tbtn\" onclick=\"navigator.clipboard.writeText(document.getElementById('mBody').value);toast('Copiat.')\">Copiază</button>\r\n      <button class=\"tbtn\" onclick=\"sendMailto('${c.id}',${M.ci})\">Deschide în Mail</button>\r\n      <button class=\"tbtn crimson\" onclick=\"sendEmailMake('${c.id}',${M.ci})\">Trimite prin Make</button></div>`;\r\n}\r\nfunction fill(t,c,p){const first=(p.nume||\"\").split(\" \")[0];const cal=M.vlad?config.calendlyVlad:(config.calendly||config.calendlyVlad);\r\n  return t.replace(/{companie}/g,c.nume).replace(/{prenume}/g,first).replace(/{nume}/g,p.nume).replace(/{functie}/g,p.rol)\r\n   .replace(/{suma}/g,c.suma!=null?lei(c.suma):(M.limba===\"en\"?\"a significant amount\":\"o sumă semnificativă\"))\r\n   .replace(/{caz}/g,M.caz||(M.limba===\"en\"?\"a medical case\":\"un caz medical\")).replace(/{proiect}/g,M.proiect||\"\")\r\n   .replace(/{calendly}/g,cal||\"[link programare]\").replace(/{link20}/g,config.link20).replace(/{link230}/g,config.link230)\r\n   .replace(/{ong}/g,config.ongNume||\"organizația noastră\")\r\n   .replace(/{responsabil}/g,c.responsabil||config.eu||\"echipă\")}\r\nfunction genMsg(c,p){const bucket=(M.canal===\"whatsapp\"||M.canal===\"sms\")?\"linkedin\":M.canal;const t=T[bucket][M.context][M.limba];return{s:t.s?fill(t.s,c,p):\"\",b:fill(t.b,c,p)}}\r\nfunction toE164(tel){let d=(tel||\"\").replace(/[^\\d+]/g,\"\");if(d.startsWith(\"+\"))return d.slice(1);if(d.startsWith(\"0\"))return \"40\"+d.slice(1);return d}\r\nfunction sendWhatsapp(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];if(!p.telefon){toast(\"Telefon nerevelat pentru acest contact.\");return}window.open(`https://wa.me/${toE164(p.telefon)}?text=${encodeURIComponent(document.getElementById(\"mBody\").value)}`,\"_blank\");logAct(c,\"mesaj\",\"WhatsApp către \"+p.nume);advance(c,\"telefon\");closeOv(\"msgOverlay\")}\r\nfunction sendSms(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];if(!p.telefon){toast(\"Telefon nerevelat pentru acest contact.\");return}window.open(`sms:${p.telefon.replace(/\\s+/g,\"\")}?body=${encodeURIComponent(document.getElementById(\"mBody\").value)}`);logAct(c,\"mesaj\",\"SMS către \"+p.nume);advance(c,\"telefon\");closeOv(\"msgOverlay\")}\r\nfunction sendWhatsappMake(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];if(!p.telefon){toast(\"Telefon nerevelat pentru acest contact.\");return}runMake(\"whatsapp\",{companie:c.nume,cui:c.cui,catre:{nume:p.nume,telefon:p.telefon},mesaj:document.getElementById(\"mBody\").value,responsabil:c.responsabil});logAct(c,\"mesaj\",\"WhatsApp (Make) către \"+p.nume);advance(c,\"telefon\");closeOv(\"msgOverlay\");toast(\"Trimis către Make (WhatsApp).\")}\r\nfunction sendSmsMake(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];if(!p.telefon){toast(\"Telefon nerevelat pentru acest contact.\");return}runMake(\"sms\",{companie:c.nume,cui:c.cui,catre:{nume:p.nume,telefon:p.telefon},mesaj:document.getElementById(\"mBody\").value,responsabil:c.responsabil});logAct(c,\"mesaj\",\"SMS (Make) către \"+p.nume);advance(c,\"telefon\");closeOv(\"msgOverlay\");toast(\"Trimis către Make (SMS).\")}\r\nfunction sendLinkedin(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];navigator.clipboard.writeText(document.getElementById(\"mBody\").value);if(p.linkedin)window.open(p.linkedin,\"_blank\");logAct(c,\"mesaj\",\"Mesaj LinkedIn către \"+p.nume);advance(c,\"mesaj\");closeOv(\"msgOverlay\");toast(\"Copiat — lipește în conversația LinkedIn.\")}\r\n/* Subsol standard obligatoriu (GDPR): identitatea expeditorului + sursa datelor (art.14) + dezabonare. Se adaugă automat la fiecare email. */\r\nfunction emailFooterText(){const nume=config.ongNume||\"\";const email=config.ongEmail||\"\";const site=config.ongSite||\"\";const linie2=[nume,email,site].filter(Boolean).join(\" · \");return \"\\n\\n—\\n\"+linie2+\"\\nȚi-am scris pentru un posibil parteneriat (comunicare B2B, interes legitim); datele de contact provin din surse profesionale.\\nDacă nu vrei să mai primești mesaje, răspunde cu „dezabonare”\"+(email?\" sau scrie la \"+email:\"\")+\".\";}\r\nfunction emailFooterHtml(){return emailFooterText().replace(/\\n/g,\"<br>\");}\r\n/* Semnătura persoanei logate (config.eu), setată în ⚙ Setări. */\r\nfunction semnaturaEu(){return (config.semnaturi&&config.eu&&config.semnaturi[config.eu])||\"\";}\r\n/* Iconițe plic pentru statusul de deschidere în istoricul de activitate. */\r\nconst MAIL_OPEN_SVG='<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 10.5V19a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-8.5\"/><path d=\"m3 10.5 9-6.5 9 6.5\"/><path d=\"m3 10.5 9 6 9-6\"/></svg>';\r\nconst MAIL_CLOSED_SVG='<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"m3 7 9 6 9-6\"/></svg>';\r\nfunction openStatusHtml(mid){if(!mid)return '';const v=EMAIL_OPENS[mid];if(v)return `<div style=\"margin-top:4px;display:inline-flex;align-items:center;gap:5px;color:#0a7a52;font-weight:700;font-size:12px\">${MAIL_OPEN_SVG}Deschis · ${esc(new Date(v).toLocaleString(\"ro-RO\"))}</div>`;return `<div style=\"margin-top:4px;display:inline-flex;align-items:center;gap:5px;color:#c0392b;font-weight:700;font-size:12px\">${MAIL_CLOSED_SVG}Nedeschis încă</div>`;}\r\nfunction sendMailto(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];if(p.consimtamant===\"dezabonat\"){toast(\"Contact dezabonat — nu trimite email.\");return}if(!p.email){toast(\"Email nerevelat — folosește Make sau revelează.\");return}window.open(`mailto:${p.email}?subject=${encodeURIComponent(document.getElementById(\"mSubj\").value)}&body=${encodeURIComponent(document.getElementById(\"mBody\").value+(semnaturaEu()?\"\\n\\n\"+semnaturaEu():\"\")+emailFooterText())}`);logAct(c,\"email\",\"Email către \"+p.nume+\": \"+document.getElementById(\"mSubj\").value);advance(c,\"email\");closeOv(\"msgOverlay\")}\r\nfunction sendEmailMake(id,ci){const c=data.find(x=>x.id===id),p=c.contacte[ci];if(p.consimtamant===\"dezabonat\"){toast(\"Contact dezabonat — nu trimite email.\");return}if(!p.email){toast(\"Contactul nu are email.\");return}const mid=\"m\"+Date.now().toString(36)+\"-\"+Math.random().toString(36).slice(2,7);const corp=(document.getElementById(\"mBody\").value||\"\").replace(/\\n/g,\"<br>\")+(semnaturaEu()?\"<br><br>\"+semnaturaEu().replace(/\\n/g,\"<br>\"):\"\")+emailFooterHtml()+'<img src=\"'+location.origin+API_BASE+'/crm-track/'+mid+'.gif\" width=\"1\" height=\"1\" alt=\"\">';runMake(\"email\",{companie:c.nume,cui:c.cui,catre:{nume:p.nume,email:p.email,linkedin:p.linkedin},subiect:document.getElementById(\"mSubj\").value,mesaj:corp,mid:mid,responsabil:c.responsabil});logAct(c,\"email\",\"Email (Make) către \"+p.nume+\": \"+document.getElementById(\"mSubj\").value,mid);advance(c,\"email\");closeOv(\"msgOverlay\")}\r\nfunction advance(c,k){if(stIdx(c.status)<stIdx(k)){c.status=k;logAct(c,\"status\",\"→ \"+stLabel(k))}pushCompany(c);renderList()}\r\n\r\n/* ============ MAKE ============ */\r\nfunction runMake(actiune,payload){\r\n  fetch(API_BASE+\"/crm-make\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(Object.assign({actiune,ts:Date.now(),de:config.eu},payload))})\r\n    .then(r=>r.json().catch(()=>({ok:false})))\r\n    .then(j=>toast(j&&j.ok?\"Trimis prin Make ✓ (\"+actiune+\")\":\"Make a răspuns cu eroare — verifică scenariul\"))\r\n    .catch(()=>toast(\"Make: conexiune eșuată.\"))}\r\nfunction postMake(actiune,payload){return fetch(API_BASE+\"/crm-make\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(Object.assign({actiune,ts:Date.now(),de:config.eu},payload))}).catch(()=>{})}\r\nasync function anafBulk(){const list=data.filter(c=>(c.cui||\"\").replace(/\\D/g,\"\"));if(!list.length){toast(\"Nicio firmă cu CUI.\");return}if(list.length>90&&!confirm(\"cuiscan permite ~100 cereri/oră. Ai \"+list.length+\" firme — continui?\"))return;let done=0,ok=0;showWait(\"Aduc bilanțuri din cuiscan… \",Math.ceil(list.length*0.8)+10);for(const c of list){const cui=(c.cui||\"\").replace(/\\D/g,\"\");try{const r=await fetch(API_BASE+\"/crm-anaf?action=financials&cui=\"+cui);const arr=await r.json();if(Array.isArray(arr)&&arr.length){const f=arr[0];if(f.cifraAfaceri!=null)c.ca=f.cifraAfaceri;if(f.profitNet!=null)c.profit=f.profitNet;if(f.profitBrut!=null&&f.profitNet!=null)c.impozit=Math.round(f.profitBrut-f.profitNet);if(f.nrAngajati!=null)c.nrAngajati=f.nrAngajati;c.profitTip=\"net\";c.sursaFin=\"bilanț \"+(f.an||\"\")+\" (ANAF/cuiscan)\";recompSuma(c);c.updatedAt=Date.now();saveFS(c);ok++}}catch(e){}done++;await new Promise(res=>setTimeout(res,650))}hideWait(\"Gata — \"+ok+\"/\"+done+\" firme cu bilanț (salvate în Firestore)\");saveCache();renderList();if(selectedId)renderDetail()}\r\nlet waitTimer=null;\r\nfunction showWait(msg,maxSec){clearInterval(waitTimer);const el=document.getElementById(\"waitBar\");if(!el)return;let rem=maxSec||60;const upd=()=>{el.innerHTML='<span class=\"spin\"></span> '+esc(msg)+' <b>mai ~'+(rem>0?rem:0)+'s</b>';rem--};upd();el.classList.add(\"on\");waitTimer=setInterval(upd,1000)}\r\nfunction hideWait(done){clearInterval(waitTimer);waitTimer=null;const el=document.getElementById(\"waitBar\");if(!el)return;if(done){el.innerHTML='✓ '+esc(done);setTimeout(()=>el.classList.remove(\"on\"),2600)}else el.classList.remove(\"on\")}\r\nasync function anafOne(id){const c=data.find(x=>x.id===id);if(!c)return;const cui=(c.cui||\"\").replace(/\\D/g,\"\");if(!cui){toast(\"Firma n-are CUI.\");return}showWait(\"Aduc datele pentru \"+c.nume+\" (cuiscan)…\",25);try{const [rf,rc]=await Promise.all([fetch(API_BASE+\"/crm-anaf?action=financials&cui=\"+cui),fetch(API_BASE+\"/crm-anaf?action=company&cui=\"+cui)]);const arr=await rf.json().catch(()=>[]);const co=await rc.json().catch(()=>({}));let any=false;if(Array.isArray(arr)&&arr.length){const f=arr[0];if(f.cifraAfaceri!=null)c.ca=f.cifraAfaceri;if(f.profitNet!=null)c.profit=f.profitNet;if(f.profitBrut!=null&&f.profitNet!=null)c.impozit=Math.round(f.profitBrut-f.profitNet);if(f.nrAngajati!=null)c.nrAngajati=f.nrAngajati;c.profitTip=\"net\";c.sursaFin=\"bilanț \"+(f.an||\"\")+\" (ANAF/cuiscan)\";recompSuma(c);any=true}if(co&&!co.error){if(co.codCaen&&!c.caen)c.caen=co.codCaen;if(co.nrRegCom&&!c.nrRegCom)c.nrRegCom=co.nrRegCom;if(co.adresa&&!c.adresa)c.adresa=co.adresa;if(co.judet&&!c.judet)c.judet=co.judet;if(co.localitate&&!c.localitate)c.localitate=co.localitate;if(co.dataInregistrare&&!c.anInfiintare){const y=parseInt((\"\"+co.dataInregistrare).slice(0,4));if(y)c.anInfiintare=y}if(co.administratori&&co.administratori.length&&!c.administrator)c.administrator=co.administratori.map(a=>a.name).filter(Boolean).join(\", \");any=true}if(!any){hideWait();toast(\"Fără date la cuiscan pentru \"+c.nume+\".\");return}pushCompany(c);hideWait(\"Date aduse din ANAF/cuiscan\");if(selectedId===id)renderDetail()}catch(e){hideWait();toast(\"cuiscan n-a răspuns — reîncearcă în câteva secunde.\")}}\r\n\r\n/* ============ TOP 10 ============ */\r\nlet topFilt={judet:\"\",responsabil:\"\",q:\"\",d177:false,mec20:false,caz:false,sumaMin:\"\",contact:\"\"};\r\nlet topPg=0;\r\nfunction setTopFilt(k,v){topFilt[k]=v;topPg=0;renderTop()}\r\nfunction setTopPg(n){topPg=n;renderTop();if(window.scrollTo)window.scrollTo(0,0);}\r\nfunction renderTop(){const q=(topFilt.q||\"\").toLowerCase().trim(),sMin=topFilt.sumaMin?parseFloat(topFilt.sumaMin):NaN;\r\n  const all=[...data].filter(c=>c.suma!=null)\r\n    .filter(c=>!topFilt.judet||canonJud(c.judet)===topFilt.judet)\r\n    .filter(c=>!topFilt.responsabil||(c.responsabil||\"\")===topFilt.responsabil)\r\n    .filter(c=>!q||c.nume.toLowerCase().includes(q))\r\n    .filter(c=>!topFilt.d177||c.d177)\r\n    .filter(c=>!topFilt.mec20||c.mec20)\r\n    .filter(c=>!topFilt.caz||c.caz)\r\n    .filter(c=>!topFilt.contact||(topFilt.contact===\"cu\"?(c.contacte||[]).length>0:!(c.contacte||[]).length))\r\n    .filter(c=>isNaN(sMin)||c.suma>=sMin)\r\n    .sort((a,b)=>b.suma-a.suma).slice(0,2000);\r\n  const PAGE=50,total=all.length,pages=Math.max(1,Math.ceil(total/PAGE));if(topPg>pages-1)topPg=pages-1;if(topPg<0)topPg=0;const start=topPg*PAGE,rows=all.slice(start,start+PAGE);\r\n  const pager=`<div style=\"display:flex;align-items:center;gap:10px;justify-content:center;margin:12px 0;flex-wrap:wrap\"><button class=\"tbtn sm\" ${topPg<=0?\"disabled\":\"\"} onclick=\"setTopPg(${topPg-1})\">← Înapoi</button><span style=\"font-size:13px;color:var(--muted)\">Pagina <input type=\"number\" min=\"1\" max=\"${pages}\" value=\"${topPg+1}\" onchange=\"setTopPg((parseInt(this.value,10)||1)-1)\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();setTopPg((parseInt(this.value,10)||1)-1)}\" title=\"Scrie numărul paginii și Enter\" style=\"width:56px;text-align:center;border:1px solid var(--line);border-radius:6px;padding:2px 4px;font:inherit;font-weight:700\"> din <b>${pages}</b> · ${total.toLocaleString(\"ro-RO\")} firme</span><button class=\"tbtn sm\" ${topPg>=pages-1?\"disabled\":\"\"} onclick=\"setTopPg(${topPg+1})\">Înainte →</button></div>`;\r\n  const _jseen={};data.forEach(function(c){const cj=canonJud(c.judet);if(cj)_jseen[cj]=1;});const jset=Object.keys(_jseen).sort((a,b)=>a.localeCompare(b,\"ro\"));\r\n  document.getElementById(\"topPage\").innerHTML=`<h1>Top 2000 companii</h1><p class=\"lead\">După sumă sponsorizabilă estimată. Încarcă mai multe firme (⏬ Tot) ca să vezi tot topul.</p>\r\n   <div class=\"topfilt\">\r\n     <select onchange=\"setTopFilt('judet',this.value)\"><option value=\"\">Toate județele</option>${jset.map(j=>`<option${j===topFilt.judet?\" selected\":\"\"}>${esc(j)}</option>`).join(\"\")}</select>\r\n     <select onchange=\"setTopFilt('responsabil',this.value)\"><option value=\"\">Toți responsabilii</option>${ECHIPA.map(r=>`<option${r===topFilt.responsabil?\" selected\":\"\"}>${esc(r)}</option>`).join(\"\")}</select>\r\n     <input placeholder=\"Caută companie…\" value=\"${esc(topFilt.q)}\" oninput=\"setTopFilt('q',this.value)\">\r\n     <input type=\"number\" placeholder=\"Sumă min (lei)\" value=\"${esc(topFilt.sumaMin)}\" oninput=\"setTopFilt('sumaMin',this.value)\" style=\"width:130px\">\r\n     <button class=\"chip\" aria-pressed=\"${topFilt.caz}\" onclick=\"setTopFilt('caz',!topFilt.caz)\">Caz</button>\r\n     <button class=\"chip\" aria-pressed=\"${topFilt.d177}\" onclick=\"setTopFilt('d177',!topFilt.d177)\">prin D177</button>\r\n     <button class=\"chip\" aria-pressed=\"${topFilt.mec20}\" onclick=\"setTopFilt('mec20',!topFilt.mec20)\">prin 20% (caz)</button>\r\n     <button class=\"chip\" aria-pressed=\"${topFilt.contact==='cu'}\" onclick=\"setTopFilt('contact',topFilt.contact==='cu'?'':'cu')\">👤 Cu contact</button>\r\n     <button class=\"chip\" aria-pressed=\"${topFilt.contact==='fara'}\" onclick=\"setTopFilt('contact',topFilt.contact==='fara'?'':'fara')\">Fără contact</button>\r\n     <button class=\"chip\" onclick=\"topFilt={judet:'',responsabil:'',q:'',d177:false,mec20:false,caz:false,sumaMin:'',contact:''};renderTop()\">✕ curăță</button>\r\n   </div>\r\n   ${pager}\r\n   <table class=\"rtable\"><thead><tr><th>#</th><th>Companie</th><th>Județ</th><th>Sumă disponibilă</th><th>Responsabil</th><th>Status</th></tr></thead><tbody>\r\n   ${rows.map((c,i)=>{const chk=`<input type=\"checkbox\" ${c.lucrat?\"checked\":\"\"} onclick=\"event.stopPropagation();toggleLucrat('${c.id}',this.checked)\" title=\"Bifează dacă ai lucrat pe firma asta\" style=\"margin-right:9px;vertical-align:middle;cursor:pointer;width:15px;height:15px;accent-color:#0a7a52\">`;return `<tr onclick=\"openFirmaNewTab('${c.id}')\" style=\"cursor:pointer\" title=\"Deschide în filă nouă\"><td class=\"rank\">${start+i+1}</td><td>${chk}<b>${esc(tc(c.nume))}</b> ${flags(c)} ${(c.contacte||[]).length?`<span class=\"badge\" title=\"Persoane de contact\">👤 ${c.contacte.length}</span>`:`<span class=\"badge\" style=\"color:#c0392b;border-color:#f0dede\" title=\"Nicio persoană de contact\">fără contact</span>`}</td><td>${esc(c.judet||\"\")}</td><td class=\"num\"><b>${lei(c.suma)}</b> <span class=\"loc\">${eur(c.suma)}</span></td><td>${esc(c.responsabil||\"—\")}</td><td><span class=\"badge\">${esc(stLabel(c.status))}</span></td></tr>`;}).join(\"\")||'<tr><td colspan=\"6\" style=\"text-align:center;color:var(--muted)\">—</td></tr>'}\r\n   </tbody></table>${pager}`}\r\n// Bifă manuală „am lucrat pe firma asta\" (Top 100). O pui tu; se salvează și rămâne bifată.\r\nfunction toggleLucrat(id,on){if(!canEdit()){toast(\"Editare permisă doar echipei.\");renderTop();return;}const c=data.find(x=>x.id===id);if(!c)return;c.lucrat=!!on;pushCompany(c);}\r\nfunction gotoCo(id){selectedId=id;document.querySelector('.tab[data-view=\"companii\"]').click();document.body.classList.add(\"showing-detail\")}\r\n// Deschide firma într-o FILĂ NOUĂ (din Top) — pagina reală /crm-pj?co=<id>, ca să rămâi în Top.\r\nfunction openFirmaNewTab(id){var base=\"/crm-pj\";try{if(window.parent&&window.parent!==window&&window.parent.location&&window.parent.location.pathname)base=window.parent.location.pathname;}catch(e){}window.open(base+\"?co=\"+encodeURIComponent(id),\"_blank\");}\r\n\r\n/* ============ RAPOARTE ============ */\r\nfunction renderRap(){const total=data.reduce((s,c)=>s+(c.suma||0),0),sponsorizat=data.reduce((s,c)=>s+(c.sumaSponsorizata||0),0),recurente=data.filter(c=>c.recurent).length,calde=data.filter(c=>c.priorGivingNoi).length;\r\n  const contacteTotal=data.reduce((s,c)=>s+c.contacte.length,0),emails=data.reduce((s,c)=>s+c.contacte.filter(p=>p.email).length,0),linkedins=data.reduce((s,c)=>s+c.contacte.filter(p=>p.linkedin).length,0),phones=data.reduce((s,c)=>s+c.contacte.filter(p=>p.telefon).length,0);\r\n  const forecast=data.reduce((s,c)=>s+expVal(c),0);const nSpon=data.filter(c=>c.status===\"sponsorizat\").length,nResp=data.filter(c=>c.status===\"respins\").length;\r\n  const winRate=(nSpon+nResp)?Math.round(100*nSpon/(nSpon+nResp)):0;const gifts=data.filter(c=>c.sumaSponsorizata).map(c=>c.sumaSponsorizata);const avgGift=gifts.length?Math.round(gifts.reduce((a,b)=>a+b,0)/gifts.length):0;\r\n  const mari=data.filter(c=>(c.sumaSponsorizata||c.suma||0)>20000).sort((a,b)=>(b.sumaSponsorizata||b.suma||0)-(a.sumaSponsorizata||a.suma||0));\r\n  document.getElementById(\"rapPage\").innerHTML=`<h1>Rapoarte</h1><p class=\"lead\">Sinteză pipeline, totaluri și companii peste 20.000 RON.</p>\r\n    <div style=\"margin-bottom:14px;display:flex;gap:8px;flex-wrap:wrap\"><button class=\"tbtn sm crimson\" onclick=\"raportPDF()\">⬇ Raport PDF</button><button class=\"tbtn sm\" onclick=\"exportRaport20k()\">⬇ Excel &gt;20k</button><button class=\"tbtn sm\" onclick=\"exportBackup()\">💾 Copie de siguranță</button><label class=\"tbtn sm\" style=\"cursor:pointer\">⬆ Restaurează<input type=\"file\" hidden accept=\".json,application/json\" onchange=\"if(this.files[0])importBackup(this.files[0]);this.value=''\"></label></div>\r\n    <div class=\"kpis\">\r\n    <div class=\"kpi\"><div class=\"k\">Total companii</div><div class=\"v\">${data.length}</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Total contacte</div><div class=\"v\">${contacteTotal}</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Contacte email</div><div class=\"v\">${emails}</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Contacte LinkedIn</div><div class=\"v\">${linkedins}</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Nr. de telefon</div><div class=\"v\">${phones}</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Sumă totală de redirecționat</div><div class=\"v\" style=\"color:var(--teal)\">${Number(total).toLocaleString(\"ro-RO\")} lei</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Forecast ponderat</div><div class=\"v\" style=\"color:var(--violet)\">${Number(forecast).toLocaleString(\"ro-RO\")} lei</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Rată de câștig</div><div class=\"v\">${winRate}%</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Gift mediu</div><div class=\"v\">${Number(avgGift).toLocaleString(\"ro-RO\")} lei</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Sponsorizat</div><div class=\"v\">${Number(sponsorizat).toLocaleString(\"ro-RO\")} lei</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Lead-uri calde</div><div class=\"v\" style=\"color:var(--crimson)\">${calde}</div></div>\r\n    <div class=\"kpi\"><div class=\"k\">Recurente</div><div class=\"v\">${recurente}</div></div></div>\r\n    <div id=\"sponsReport\"></div>\r\n    <div class=\"section-h\" style=\"margin-top:24px\"><h2>Raport activitate — peste 20.000 RON</h2><button class=\"tbtn sm\" onclick=\"exportRaport20k()\">⬇ Export</button></div>\r\n    <table class=\"rtable\"><thead><tr><th>Companie</th><th>Sumă</th><th>Responsabil</th><th>Status</th><th>Frecvență</th><th>Recurent</th></tr></thead><tbody>\r\n    ${mari.map(c=>`<tr onclick=\"gotoCo('${c.id}')\" style=\"cursor:pointer\"><td><b>${esc(tc(c.nume))}</b> ${flags(c)}</td><td class=\"num\">${lei(c.sumaSponsorizata||c.suma)}</td><td>${esc(c.responsabil||\"—\")}</td><td><span class=\"badge\">${esc(stLabel(c.status))}</span></td><td>${esc(c.frecventa||\"—\")}</td><td>${c.recurent?\"Da\":\"Nu\"}</td></tr>`).join(\"\")||'<tr><td colspan=\"6\" style=\"text-align:center;color:var(--muted)\">—</td></tr>'}\r\n    </tbody></table>`;\r\n  loadSponsReport();\r\n}\r\n\r\nlet sponsData=[],sponsAn=\"\",sponsQ=\"\",chartSponsQ=null;\r\nasync function loadSponsReport(){\r\n  const el=document.getElementById(\"sponsReport\");if(!el)return;\r\n  el.innerHTML='<div class=\"loc\">Se \\u00eencarc\\u0103 sponsoriz\\u0103rile\\u2026</div>';\r\n  try{\r\n    const r=await fetch(API_BASE+\"/crm-companies?status=won&limit=1000\");\r\n    if(!r.ok){el.innerHTML='<div class=\"loc\">Sponsoriz\\u0103ri: '+r.status+'</div>';return}\r\n    const j=await r.json();const firms=j.items||[];\r\n    sponsData=[];\r\n    firms.forEach(c=>{const list=(c.sponsorizari&&c.sponsorizari.length)?c.sponsorizari:[{suma:c.sumaSponsorizata,data:c.dataSponsorizare||\"\"}];list.forEach(sx=>sponsData.push({nume:c.nume,cui:c.cui,responsabil:c.responsabil||\"\\u2014\",suma:sx.suma||0,data:sx.data||\"\",caz:sx.caz||\"\",id:c.id}))});\r\n    renderSpons();\r\n  }catch(e){el.innerHTML='<div class=\"loc\">Sponsoriz\\u0103ri \\u2014 eroare re\\u021bea: '+esc(e.message)+'</div>'}\r\n}\r\nfunction sponsFiltered(){let rows=sponsData.slice();\r\n  if(sponsAn)rows=rows.filter(e=>(e.data||\"\").slice(0,4)===sponsAn);\r\n  if(sponsQ){const qm={Q1:[\"01\",\"02\",\"03\"],Q2:[\"04\",\"05\",\"06\"],Q3:[\"07\",\"08\",\"09\"],Q4:[\"10\",\"11\",\"12\"]}[sponsQ];rows=rows.filter(e=>qm.indexOf((e.data||\"\").slice(5,7))>=0)}\r\n  return rows;}\r\nfunction renderSpons(){\r\n  const el=document.getElementById(\"sponsReport\");if(!el)return;\r\n  const years=[...new Set(sponsData.map(e=>(e.data||\"\").slice(0,4)).filter(Boolean))].sort().reverse();\r\n  const rows=sponsFiltered();\r\n  const total=rows.reduce((s,e)=>s+(e.suma||0),0);\r\n  const byResp={};rows.forEach(e=>byResp[e.responsabil]=(byResp[e.responsabil]||0)+(e.suma||0));\r\n  const byMonth={};rows.forEach(e=>{const m=(e.data||\"\").slice(0,7)||\"\\u2014\";byMonth[m]=(byMonth[m]||0)+(e.suma||0)});\r\n  const byQ={T1:0,T2:0,T3:0,T4:0};rows.forEach(e=>{const mo=(e.data||\"\").slice(5,7);if(!/^\\d{2}$/.test(mo))return;const qn=Math.floor((parseInt(mo,10)-1)/3)+1;byQ[\"T\"+qn]+=(e.suma||0)});\r\n  const qKeys=[\"T1\",\"T2\",\"T3\",\"T4\"];const qTotal=qKeys.reduce((s,k)=>s+byQ[k],0);\r\n  const months=Object.keys(byMonth).sort();\r\n  const byFirm={};rows.forEach(e=>{const f=byFirm[e.id]||(byFirm[e.id]={nume:e.nume,responsabil:e.responsabil,suma:0,last:\"\"});f.suma+=e.suma||0;if((e.data||\"\")>f.last)f.last=e.data||\"\"});\r\n  const firmRows=Object.values(byFirm).sort((a,b)=>b.suma-a.suma);\r\n  el.innerHTML=`<div class=\"section-h\" style=\"margin-top:24px\"><h2>Sponsoriz\\u0103ri \\u00eencasate</h2><span style=\"color:var(--crimson);font-weight:800;font-size:20px\">${lei(total)}</span></div>`\r\n    +`<div style=\"display:flex;gap:8px;margin-bottom:12px;align-items:center;flex-wrap:wrap\">`\r\n    +`<select onchange=\"sponsAn=this.value;renderSpons()\" style=\"border:1px solid var(--line);border-radius:8px;padding:6px 8px;font:inherit\"><option value=\"\">To\\u021bi anii</option>${years.map(y=>`<option ${sponsAn===y?\"selected\":\"\"}>${y}</option>`).join(\"\")}</select>`\r\n    +`<select onchange=\"sponsQ=this.value;renderSpons()\" style=\"border:1px solid var(--line);border-radius:8px;padding:6px 8px;font:inherit\"><option value=\"\">Tot anul</option>${[\"Q1\",\"Q2\",\"Q3\",\"Q4\"].map(q=>`<option ${sponsQ===q?\"selected\":\"\"}>${q}</option>`).join(\"\")}</select>`\r\n    +`<button class=\"tbtn sm crimson\" onclick=\"exportSpons()\">\\u2b07 Export Excel</button></div>`\r\n    +`<div class=\"kpis\" style=\"margin-bottom:12px\">${Object.keys(byResp).sort().map(rr=>`<div class=\"kpi\"><div class=\"k\">${esc(rr)}</div><div class=\"v\" style=\"color:var(--crimson)\">${lei(byResp[rr])}</div></div>`).join(\"\")||'<div class=\"loc\">Nicio sponsorizare pentru filtrul ales.</div>'}</div>`\r\n    +(qTotal>0?`<div class=\"chart-card\" style=\"margin-bottom:12px\"><div style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px\"><h3 style=\"margin:0\">Sponsorizări pe trimestre${sponsAn?\" · \"+esc(sponsAn):\" · toți anii\"}</h3><select onchange=\"sponsAn=this.value;renderSpons()\" style=\"border:1px solid var(--line);border-radius:8px;padding:5px 8px;font:inherit;font-size:13px\"><option value=\"\">Toți anii</option>${years.map(y=>`<option ${sponsAn===y?\"selected\":\"\"}>${y}</option>`).join(\"\")}</select></div><div style=\"height:250px\"><canvas id=\"sponsQChart\"></canvas></div></div>`:'')\r\n    +(months.length?`<table class=\"rtable\"><thead><tr><th>Lun\\u0103</th><th>Sum\\u0103 \\u00eencasat\\u0103</th></tr></thead><tbody>${months.map(m=>`<tr><td>${m}</td><td class=\"num\">${lei(byMonth[m])}</td></tr>`).join(\"\")}</tbody></table>`:'')\r\n    +`<table class=\"rtable\" style=\"margin-top:12px\"><thead><tr><th>Companie</th><th>Sum\\u0103 total\\u0103</th><th>Ultima dat\\u0103</th><th>Responsabil</th></tr></thead><tbody>`\r\n    +(firmRows.length?firmRows.map(c=>`<tr><td><b>${esc(tc(c.nume))}</b></td><td class=\"num\">${lei(c.suma)}</td><td>${c.last?new Date(c.last).toLocaleDateString(\"ro-RO\"):\"\\u2014\"}</td><td>${esc(c.responsabil||\"\\u2014\")}</td></tr>`).join(\"\"):'<tr><td colspan=\"4\" style=\"text-align:center;color:var(--muted)\">Nicio sponsorizare \\u00eencasat\\u0103 \\u00een perioada aleas\\u0103.</td></tr>')\r\n    +`</tbody></table>`;\r\n  if(typeof Chart!==\"undefined\"){if(chartSponsQ){chartSponsQ.destroy();chartSponsQ=null;}const cv=document.getElementById(\"sponsQChart\");if(cv&&qTotal>0)chartSponsQ=new Chart(cv,{type:\"pie\",data:{labels:qKeys,datasets:[{data:qKeys.map(k=>byQ[k]),backgroundColor:[\"#C81E4A\",\"#B7791F\",\"#7C3AED\",\"#0E7C6B\"],borderWidth:2,borderColor:\"#ffffff\"}]},options:{plugins:{legend:{position:\"right\"},tooltip:{callbacks:{label:ctx=>ctx.label+\": \"+Number(ctx.raw).toLocaleString(\"ro-RO\")+\" lei (\"+(qTotal?Math.round(ctx.raw/qTotal*100):0)+\"%)\"}}},maintainAspectRatio:false}});}\r\n}\r\nfunction exportSpons(){if(!isAdmin()){toast(\"Export permis doar administratorului.\");return}if(typeof XLSX===\"undefined\"){toast(\"Excel indisponibil.\");return}\r\n  const rows=sponsFiltered().map(e=>({Companie:tc(e.nume),CUI:e.cui||\"\",Caz:e.caz||\"\",Suma:e.suma,Data:e.data||\"\",Responsabil:e.responsabil||\"\"}));\r\n  if(!rows.length){toast(\"Nimic de exportat pentru filtrul ales.\");return}\r\n  const ws=XLSX.utils.json_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,\"Sponsorizari\");\r\n  const suf=(sponsAn||\"toti\")+(sponsQ?\"-\"+sponsQ:\"\");XLSX.writeFile(wb,\"sponsorizari-\"+suf+\"-\"+today()+\".xlsx\");toast(\"Export Excel.\");}\r\n/* ============ SARCINI ============ */\r\nfunction prioRank(t){return t.prioritate===\"urgent\"?0:t.prioritate===\"important\"?1:2}\r\nfunction prioBadge(t){return t.prioritate===\"urgent\"?'<span class=\"due red\" style=\"margin-right:6px\">URGENT</span>':t.prioritate===\"important\"?'<span class=\"due\" style=\"margin-right:6px;background:#FBF1DE;color:var(--amber)\">Important</span>':''}\r\nlet taskFilter=null;\r\n// Sarcină întârziată: scadența a trecut, SAU e azi dar a trecut ora programată (sfârșitul intervalului).\r\nfunction taskOverdue(t){if(!t||t.gata||!t.scadenta)return false;var azi=new Date().toISOString().slice(0,10);if(t.scadenta<azi)return true;\r\n  if(t.scadenta===azi&&t.ora){var m=(\"\"+t.ora).match(/(\\d{1,2}):(\\d{2})(?:\\s*-\\s*(\\d{1,2}):(\\d{2}))?/);if(m){var eh=(m[3]!=null)?+m[3]:+m[1],em=(m[3]!=null)?+m[4]:+m[2];var now=new Date();if(now.getHours()*60+now.getMinutes()>eh*60+em)return true;}}\r\n  return false;}\r\nfunction setTaskFilter(f){taskFilter=(taskFilter===f?null:f);renderTasks();}\r\nfunction rescheduleTask(id,d){if(!canEdit())return;const t=tasks.find(x=>x.id===id);if(!t)return;t.scadenta=d||\"\";pushTasks();fsSaveTask(t);if(curView===\"sarcini\")renderTasks();if(curView===\"zi\")renderZi();renderDueBanner();toast(d?(\"Reprogramat pe \"+d):\"Scadență ștearsă\");}\r\n// „→ Mâine\": amână sarcina pe ziua de mâine.\r\nfunction postponeTask(id){if(!canEdit())return;const t=tasks.find(x=>x.id===id);if(!t)return;const d=new Date();d.setDate(d.getDate()+1);t.scadenta=d.toISOString().slice(0,10);pushTasks();fsSaveTask(t);if(curView===\"sarcini\")renderTasks();if(curView===\"zi\")renderZi();renderDueBanner();toast(\"Amânat pe mâine (\"+t.scadenta+\")\");}\r\nfunction gotoCoByName(name){const c=data.find(x=>(x.nume||\"\").toLowerCase()===(\"\"+name).toLowerCase());if(c)gotoCo(c.id);else toast(\"Firma nu e încărcată — caut-o în Companii.\");}\r\nfunction taskRowHtml(t,azi){const od=taskOverdue(t);\r\n  const comp=t.companie?` · <span onclick=\"event.stopPropagation();gotoCoByName(this.dataset.n)\" data-n=\"${esc(t.companie)}\" style=\"color:var(--crimson);cursor:pointer;text-decoration:underline\">${esc(t.companie)}</span>`:\"\";\r\n  return `<div class=\"taskrow ${t.gata?'done':''} ${od?'overdue':''}\"><input type=\"checkbox\" ${t.gata?\"checked\":\"\"} onchange=\"toggleTask('${t.id}')\"><div style=\"flex:1;min-width:0\">${prioBadge(t)}<div class=\"tt\">${esc(t.titlu)}${comp}</div><div class=\"tm\">creat de ${esc(t.creatDe||\"—\")}${t.catre?\" · către \"+esc(t.catre):\"\"}${t.ora?' · 🕒 '+esc(t.ora):\"\"}</div></div>${t.scadenta?`<span class=\"due ${od?'red':''}\">${esc(t.scadenta)}</span>`:''}<input type=\"date\" value=\"${esc(t.scadenta||'')}\" onchange=\"rescheduleTask('${t.id}',this.value)\" title=\"Reprogramează (alege data)\" style=\"width:128px;border:1px solid var(--line);border-radius:7px;padding:4px 6px;font:inherit;font-size:12px\">${(!t.gata&&t.prioritate!==\"urgent\")?`<button class=\"minibtn\" onclick=\"postponeTask('${t.id}')\" title=\"Împinge pe mâine\">→ Mâine</button>`:''}<button class=\"minibtn\" onclick=\"delTask('${t.id}')\">✕</button></div>`;}\r\nfunction renderTasks(){const azi=new Date().toISOString().slice(0,10);\r\n  const groups={};tasks.forEach(t=>{(groups[t.catre||\"—\"]=groups[t.catre||\"—\"]||[]).push(t)});\r\n  const order=[config.eu,...ECHIPA,\"—\"].filter((v,i,a)=>v&&a.indexOf(v)===i);\r\n  const eu=config.eu,mineT=tasks.filter(t=>!eu||t.catre===eu);\r\n  const cats={azi:t=>!t.gata&&t.scadenta===azi&&!taskOverdue(t),intarziate:t=>!t.gata&&taskOverdue(t),inchise:t=>!!t.gata,programate:t=>!t.gata&&t.scadenta&&t.scadenta>azi};\r\n  const card=(key,ic,lab,bg,fg)=>`<div onclick=\"setTaskFilter('${key}')\" title=\"Apasă pentru lista de sarcini\" style=\"flex:1;min-width:150px;background:${bg};border:1px solid ${taskFilter===key?fg:'var(--line)'};border-radius:14px;padding:15px 18px;cursor:pointer\"><div style=\"display:flex;align-items:center;gap:8px;color:${fg};font-weight:600;font-size:14px\"><span>${ic}</span>${lab}</div><div style=\"font-size:32px;font-weight:800;margin-top:4px\">${mineT.filter(cats[key]).length}</div></div>`;\r\n  const cards=`<div style=\"display:flex;gap:14px;flex-wrap:wrap;margin:14px 0 18px\">${card(\"azi\",\"🗓\",\"Sarcini de azi\",\"#eef4ff\",\"#2563eb\")}${card(\"intarziate\",\"⚠\",\"Sarcini întârziate\",\"#fff1f0\",\"#c0392b\")}${card(\"inchise\",\"✓\",\"Sarcini închise\",\"#eafaf1\",\"#0a7a52\")}${card(\"programate\",\"🕒\",\"Sarcini programate\",\"#f6f7f9\",\"#6b7280\")}</div>`;\r\n  let html=`<h1>Sarcini</h1><p class=\"lead\">Apasă pe un card ca să vezi lista din categoria aia. Poți reprograma fiecare sarcină și pune interval orar.</p>${cards}<button class=\"tbtn primary\" onclick=\"openTaskModal()\" style=\"margin-bottom:14px\">+ Sarcină nouă</button>`;\r\n  if(taskFilter){\r\n    const labels={azi:\"Sarcini de azi\",intarziate:\"Sarcini întârziate\",inchise:\"Sarcini închise\",programate:\"Sarcini programate\"};\r\n    const list=mineT.filter(cats[taskFilter]).slice().sort((a,b)=>(a.scadenta||\"\").localeCompare(b.scadenta||\"\"));\r\n    html+=`<div class=\"section-h\" style=\"margin-top:6px\"><h2>${labels[taskFilter]} <span class=\"badge\">${list.length}</span></h2><button class=\"minibtn\" onclick=\"setTaskFilter(null)\">✕ arată toate</button></div>`;\r\n    html+=list.length?list.map(t=>taskRowHtml(t,azi)).join(\"\"):('<div class=\"empty\">Nicio sarcină în „'+labels[taskFilter]+'\".</div>');\r\n  }else{\r\n    order.forEach(who=>{const list=(groups[who]||[]).slice().sort((a,b)=>(a.gata?1:0)-(b.gata?1:0)||prioRank(a)-prioRank(b)||(a.scadenta||\"\").localeCompare(b.scadenta||\"\"));if(!list.length)return;\r\n      const activ=list.filter(t=>!t.gata).length;\r\n      html+=`<div class=\"section-h\" style=\"margin-top:18px\"><h2>${who===config.eu?\"Ale mele\":esc(who)} <span class=\"badge\">${activ} active</span></h2></div>`;\r\n      html+=list.map(t=>taskRowHtml(t,azi)).join(\"\");\r\n    });\r\n    if(!tasks.length)html+='<div class=\"empty\">Nicio sarcină.</div>';\r\n  }\r\n  document.getElementById(\"taskPage\").innerHTML=html;\r\n}\r\nfunction renderDueBanner(){const el=document.getElementById(\"dueBanner\");if(!el)return;\r\n  const azi=new Date().toISOString().slice(0,10),dismissed=lsGet(\"dueBannerDismissed\");\r\n  const due=tasks.filter(t=>!t.gata&&t.scadenta===azi&&(!config.eu||t.catre===config.eu||!t.catre));\r\n  if(!due.length||dismissed===azi){el.style.display=\"none\";return}\r\n  el.style.display=\"flex\";\r\n  el.innerHTML=`<span style=\"font-weight:700\">⏰ Azi ai ${due.length} sarcin${due.length===1?\"ă\":\"i\"}:</span>`+due.map(t=>`<span style=\"display:inline-flex;align-items:center;gap:6px\">${prioBadge(t)}${esc(t.titlu)}${t.prioritate!==\"urgent\"?`<button class=\"minibtn\" onclick=\"postponeTask('${t.id}')\">→ Mâine</button>`:''}</span>`).join(\"\")+`<button class=\"minibtn\" onclick=\"lsSet('dueBannerDismissed','${azi}');renderDueBanner()\" style=\"margin-left:auto\">Ascunde azi</button>`;\r\n}\r\n\r\n/* ============ ZIUA MEA ============ */\r\nfunction renderZi(){const eu=config.eu,azi=new Date().toISOString().slice(0,10);\r\n  const myFollow=data.filter(c=>c.followupAt&&(!eu||c.responsabil===eu)).sort((a,b)=>a.followupAt-b.followupAt);\r\n  const myTasks=tasks.filter(t=>!t.gata&&(!eu||t.catre===eu)).sort((a,b)=>(a.scadenta||\"\").localeCompare(b.scadenta||\"\"));\r\n  const myRenew=data.filter(c=>c.nextAsk&&(!eu||c.responsabil===eu)).sort((a,b)=>(a.nextAsk||\"\").localeCompare(b.nextAsk||\"\"));\r\n  const restante=myFollow.filter(c=>isOverdue(c.followupAt)).length+myTasks.filter(t=>t.scadenta&&t.scadenta<azi).length+myRenew.filter(c=>c.nextAsk<azi).length;\r\n  document.getElementById(\"ziPage\").innerHTML=`<h1>Ziua mea${eu?\" · \"+esc(eu):\"\"}</h1>\r\n    <p class=\"lead\">${new Date().toLocaleDateString(\"ro-RO\",{weekday:\"long\",day:\"numeric\",month:\"long\",year:\"numeric\"})}${fiscalNow()?' · <b style=\"color:var(--amber)\">⏳ fereastră fiscală activă</b>':''}</p>\r\n    <div class=\"kpis\">\r\n      <div class=\"kpi\"><div class=\"k\">Restanțe</div><div class=\"v\" style=\"color:var(--crimson)\">${restante}</div></div>\r\n      <div class=\"kpi\"><div class=\"k\">De sunat</div><div class=\"v\">${myFollow.length}</div></div>\r\n      <div class=\"kpi\"><div class=\"k\">Sarcinile mele</div><div class=\"v\">${myTasks.length}</div></div>\r\n    </div>\r\n    <div class=\"section-h\" style=\"margin-top:20px\"><h2>☎ De sunat (revenire 48h)</h2></div>\r\n    ${myFollow.length?myFollow.map(c=>`<div class=\"taskrow ${isOverdue(c.followupAt)?'overdue':''}\"><div style=\"flex:1\"><div class=\"tt\">${esc(c.nume)}</div><div class=\"tm\">${esc(c.responsabil||\"\")} · ${esc(stLabel(c.status))}</div></div><span class=\"due ${isOverdue(c.followupAt)?'red':''}\">${new Date(c.followupAt).toLocaleDateString(\"ro-RO\")}</span><button class=\"minibtn\" onclick=\"gotoCo('${c.id}')\">Deschide</button><button class=\"minibtn\" onclick=\"clearFollow('${c.id}')\">✓ sunat</button></div>`).join(\"\"):'<div class=\"empty\">Nimic de sunat.</div>'}\r\n    <div class=\"section-h\" style=\"margin-top:22px\"><h2>✓ Sarcinile mele</h2></div>\r\n    ${myTasks.length?myTasks.map(t=>{const od=t.scadenta&&t.scadenta<azi;return `<div class=\"taskrow ${od?'overdue':''}\"><input type=\"checkbox\" onchange=\"toggleTask('${t.id}');renderZi()\"><div style=\"flex:1\"><div class=\"tt\">${esc(t.titlu)}</div><div class=\"tm\">${esc(t.companie||\"\")}</div></div>${t.scadenta?`<span class=\"due ${od?'red':''}\">${esc(t.scadenta)}</span>`:''}</div>`}).join(\"\"):'<div class=\"empty\">Nicio sarcină deschisă.</div>'}\r\n    ${myRenew.length?`<div class=\"section-h\" style=\"margin-top:22px\"><h2>↻ Reînnoiri de programat</h2></div>`+myRenew.map(c=>`<div class=\"taskrow ${c.nextAsk<azi?'overdue':''}\"><div style=\"flex:1\"><div class=\"tt\">${esc(c.nume)}</div><div class=\"tm\">ask: ${esc(c.nextAsk)}</div></div><button class=\"minibtn\" onclick=\"gotoCo('${c.id}')\">Deschide</button></div>`).join(\"\"):''}`;\r\n}\r\n\r\n/* ============ ACTIVITATEA MEA (raport personal, doar al meu) ============ */\r\nlet activDays=30;let activOpen={};\r\nfunction setActivDays(d){activDays=d;renderActiv()}\r\nfunction toggleActivGroup(key){activOpen[key]=!activOpen[key];renderActiv();}\r\nfunction goCalendar(){const t=document.querySelector('.tab[data-view=\"calendar\"]');if(t)t.click();}\r\nfunction renderActiv(){\r\n  const eu=config.eu||\"\";\r\n  const cut=activDays?Date.now()-activDays*86400000:0;\r\n  const azi=new Date().toISOString().slice(0,10);\r\n  const mine=[];\r\n  data.forEach(c=>{\r\n    (c.activitati||[]).forEach(a=>{if(a&&(!eu||a.de===eu)&&(a.ts||0)>=cut)mine.push({c:c,a:a});});\r\n    (c.notite||[]).forEach(n=>{if(n&&(!eu||n.de===eu)&&(n.ts||0)>=cut)mine.push({c:c,a:{ts:n.ts,tip:\"nota\",text:\"📝 \"+n.text,de:n.de}});});\r\n  });\r\n  const contacte=mine.filter(x=>x.a.tip===\"contact\").sort((p,q)=>q.a.ts-p.a.ts);\r\n  const contactate=mine.filter(x=>x.a.tip===\"mesaj\"||x.a.tip===\"apel\").sort((p,q)=>q.a.ts-p.a.ts);\r\n  const modif=mine.filter(x=>x.a.tip===\"status\"||x.a.tip===\"nota\").sort((p,q)=>q.a.ts-p.a.ts);\r\n  const rec=recentAccess.filter(r=>r&&(r.ts||0)>=cut);\r\n  const cal=[];\r\n  data.forEach(c=>{\r\n    if(c.followupAt&&(!eu||c.responsabil===eu))cal.push({d:new Date(c.followupAt).toISOString().slice(0,10),t:\"☎ Revenire telefon\",nume:c.nume,id:c.id});\r\n    if(c.nextAsk&&(!eu||c.responsabil===eu))cal.push({d:c.nextAsk,t:\"↻ Reînnoire\",nume:c.nume,id:c.id});\r\n    (c.notite||[]).forEach(n=>{if(n&&(!eu||n.de===eu))cal.push({d:n.zi||new Date(n.ts).toISOString().slice(0,10),t:\"📝 \"+(\"\"+n.text).slice(0,40),nume:c.nume,id:c.id});});\r\n  });\r\n  (typeof tasks!==\"undefined\"?tasks:[]).forEach(t=>{if(t&&!t.gata&&(!eu||t.catre===eu)&&t.scadenta)cal.push({d:t.scadenta,t:\"✓ \"+t.titlu,nume:t.companie||\"\",id:null});});\r\n  const calUp=cal.filter(x=>x.d>=azi).sort((a,b)=>a.d.localeCompare(b.d)).slice(0,14);\r\n  const row=(nume,text,ts,id)=>`<div class=\"taskrow\"><div style=\"flex:1;min-width:0\"><div class=\"tt\">${esc(nume||\"—\")}</div><div class=\"tm\">${esc(text)}</div></div><span class=\"due\">${ts?new Date(ts).toLocaleDateString(\"ro-RO\"):\"\"}</span>${id?`<button class=\"minibtn\" onclick=\"gotoCo('${id}')\">Deschide</button>`:\"\"}</div>`;\r\n  const list=(arr,fn,gol)=>arr.length?arr.slice(0,40).map(fn).join(\"\"):`<div class=\"empty\">${gol}</div>`;\r\n  // Grupat pe firmă: un rând per firmă (cu contor), click → desfășurătorul (toate intrările).\r\n  const groupRender=(section,arr,gol)=>{\r\n    if(!arr.length)return `<div class=\"empty\">${gol}</div>`;\r\n    const g={};arr.forEach(x=>{(g[x.c.id]=g[x.c.id]||{c:x.c,items:[]}).items.push(x.a);});\r\n    const groups=Object.keys(g).map(k=>g[k]).sort((a,b)=>b.items.length-a.items.length);\r\n    return groups.map(gr=>{const key=section+\":\"+gr.c.id,open=activOpen[key];const latest=gr.items.reduce((m,a)=>Math.max(m,a.ts||0),0);\r\n      const det=open?`<div style=\"margin-top:8px;border-top:1px dashed var(--line);padding-top:8px\">${gr.items.slice().sort((a,b)=>(b.ts||0)-(a.ts||0)).map(a=>`<div style=\"display:flex;gap:8px;padding:3px 0;font-size:13px;align-items:baseline\"><span style=\"flex:1;min-width:0\">${esc((\"\"+a.text).replace(/^[➕📝]\\s*/,\"\"))}</span><span class=\"loc\" style=\"white-space:nowrap\">${a.ts?new Date(a.ts).toLocaleString(\"ro-RO\"):\"\"}</span></div>`).join(\"\")}<div style=\"margin-top:6px\"><button class=\"minibtn\" onclick=\"event.stopPropagation();gotoCo('${gr.c.id}')\">Deschide firma</button></div></div>`:\"\";\r\n      return `<div class=\"taskrow\" style=\"flex-direction:column;align-items:stretch;cursor:pointer\" onclick=\"toggleActivGroup('${key}')\"><div style=\"display:flex;align-items:center;gap:8px\"><span style=\"flex:1;min-width:0\"><b>${esc(gr.c.nume)}</b> <span class=\"badge\">${gr.items.length}</span></span><span class=\"due\">${latest?new Date(latest).toLocaleDateString(\"ro-RO\"):\"\"}</span><span style=\"color:var(--muted);font-weight:700\">${open?\"▾\":\"▸\"}</span></div>${det}</div>`;\r\n    }).join(\"\");\r\n  };\r\n  const pill=(d,on)=>`<button class=\"tbtn sm\" style=\"${on?'background:var(--crimson);color:#fff;border-color:var(--crimson)':''}\" onclick=\"setActivDays(${d})\">${d?d+\" zile\":\"Tot\"}</button>`;\r\n  document.getElementById(\"activPage\").innerHTML=`<h1>Activitatea mea${eu?\" · \"+esc(eu):\"\"}</h1>\r\n    <p class=\"lead\">🔒 Doar tu vezi asta — activitatea ta din firmele încărcate. Perioadă: ${pill(7,activDays===7)} ${pill(30,activDays===30)} ${pill(90,activDays===90)} ${pill(0,!activDays)}</p>\r\n    <div class=\"kpis\">\r\n      <div class=\"kpi\"><div class=\"k\">Contacte adăugate</div><div class=\"v\">${contacte.length}</div></div>\r\n      <div class=\"kpi\"><div class=\"k\">Persoane contactate</div><div class=\"v\">${contactate.length}</div></div>\r\n      <div class=\"kpi\"><div class=\"k\">Modificări pe firme</div><div class=\"v\">${modif.length}</div></div>\r\n      <div class=\"kpi\"><div class=\"k\">Firme accesate</div><div class=\"v\">${rec.length}</div></div>\r\n    </div>\r\n    <div class=\"section-h\" style=\"margin-top:22px\"><h2>➕ Contacte adăugate</h2><span class=\"hint\">grupat pe firmă · click pentru desfășurător</span></div>\r\n    ${groupRender(\"contacte\",contacte,\"Niciun contact adăugat în perioada asta.\")}\r\n    <div class=\"section-h\" style=\"margin-top:22px\"><h2>📞 Persoane contactate</h2><span class=\"hint\">click pe firmă pentru desfășurător</span></div>\r\n    ${groupRender(\"contactate\",contactate,\"Nimeni contactat în perioada asta.\")}\r\n    <div class=\"section-h\" style=\"margin-top:22px\"><h2>✏️ Modificări pe firme</h2><span class=\"hint\">click pe firmă pentru desfășurător</span></div>\r\n    ${groupRender(\"modif\",modif,\"Nicio modificare în perioada asta.\")}\r\n    <div class=\"section-h\" style=\"margin-top:22px\"><h2>🕘 Recent accesate</h2></div>\r\n    ${rec.length?rec.slice(0,30).map(r=>{const c=data.find(x=>x.id===r.id);return row(c?c.nume:\"(firmă neîncărcată)\",\"accesată\",r.ts,c?c.id:null)}).join(\"\"):'<div class=\"empty\">Nicio firmă accesată recent.</div>'}\r\n    <div class=\"section-h\" style=\"margin-top:22px\"><h2>📅 Calendar — următoarele</h2><button class=\"minibtn\" onclick=\"goCalendar()\">Deschide calendarul</button></div>\r\n    ${calUp.length?calUp.map(x=>`<div class=\"taskrow\"><div style=\"flex:1;min-width:0\"><div class=\"tt\">${esc(x.nume||x.t)}</div><div class=\"tm\">${esc(x.t)}</div></div><span class=\"due\">${esc(x.d)}</span>${x.id?`<button class=\"minibtn\" onclick=\"gotoCo('${x.id}')\">Deschide</button>`:\"\"}</div>`).join(\"\"):'<div class=\"empty\">Nimic programat.</div>'}\r\n    <p class=\"hint\" style=\"margin-top:14px\">Notă: raportul acoperă firmele încărcate în listă. Ca să vezi tot, încarcă mai multe firme din „Companii\".</p>`;\r\n}\r\n/* ============ RAPORT PDF ============ */\r\nfunction exportBackup(){try{const dump={app:\"crm-soi\",v:SEED_VERSION,when:new Date().toISOString(),data,tasks,config};const blob=new Blob([JSON.stringify(dump)],{type:\"application/json\"});const url=URL.createObjectURL(blob);const a=document.createElement(\"a\");a.href=url;a.download=\"backup-crm-soi-\"+new Date().toISOString().slice(0,10)+\".json\";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);toast(\"Copie de siguranță descărcată.\")}catch(e){toast(\"Eroare la backup.\")}}\r\nfunction importBackup(file){const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||!Array.isArray(d.data)){toast(\"Fișier invalid.\");return}if(!confirm(\"Restaurezi din backup? Datele curente vor fi înlocuite cu \"+d.data.length+\" firme.\"))return;data.length=0;d.data.forEach(c=>data.push(c));tasks.length=0;(d.tasks||[]).forEach(t=>tasks.push(t));if(d.config)Object.assign(config,d.config);selectedId=data[0]?data[0].id:null;saveLocal();if(typeof renderAll===\"function\")renderAll();toast(\"Restaurat: \"+data.length+\" firme.\")}catch(e){toast(\"Fișier corupt sau invalid.\")}};r.readAsText(file)}\r\nfunction raportPDF(){if(!isAdmin()){toast(\"Export permis doar administratorilor organizației.\");return}if(!window.jspdf){toast(\"PDF indisponibil offline.\");return}\r\n  const dd=s=>String(s==null?\"\":s).normalize(\"NFD\").replace(/[\\u0300-\\u036f]/g,\"\");\r\n  const {jsPDF}=window.jspdf,doc=new jsPDF(),total=data.reduce((s,c)=>s+(c.suma||0),0),ct=data.reduce((s,c)=>s+c.contacte.length,0);\r\n  doc.setFontSize(15);doc.text(\"Raport prospectare corporate - salveaza o inima\",14,18);\r\n  doc.setFontSize(9);doc.setTextColor(120);doc.text(\"Generat: \"+new Date().toLocaleDateString(\"ro-RO\")+\"   \"+dd(config.eu||\"\"),14,25);\r\n  doc.setTextColor(20);doc.setFontSize(10);\r\n  doc.text(\"Companii: \"+data.length+\"    Contacte: \"+ct+\"    Suma totala de redirectionat: \"+Number(total).toLocaleString(\"ro-RO\")+\" lei\",14,33);\r\n  const top=[...data].filter(c=>c.suma!=null).sort((a,b)=>b.suma-a.suma).slice(0,15).map((c,i)=>[i+1,dd(c.nume),dd(c.judet||\"\"),Number(c.suma).toLocaleString(\"ro-RO\"),dd(c.responsabil||\"\"),dd(stLabel(c.status))]);\r\n  doc.autoTable({startY:39,head:[[\"#\",\"Companie\",\"Judet\",\"Suma sponsorizabila (lei)\",\"Responsabil\",\"Status\"]],body:top,styles:{fontSize:8},headStyles:{fillColor:[200,30,74]}});\r\n  const mari=data.filter(c=>(c.sumaSponsorizata||c.suma||0)>20000).map(c=>[dd(c.nume),Number(c.sumaSponsorizata||c.suma).toLocaleString(\"ro-RO\"),dd(c.responsabil||\"\"),dd(stLabel(c.status)),c.recurent?\"Da\":\"Nu\"]);\r\n  if(mari.length){doc.setFontSize(11);doc.text(\"Companii peste 20.000 RON\",14,doc.lastAutoTable.finalY+10);doc.autoTable({startY:doc.lastAutoTable.finalY+14,head:[[\"Companie\",\"Suma (lei)\",\"Responsabil\",\"Status\",\"Recurent\"]],body:mari,styles:{fontSize:8},headStyles:{fillColor:[14,124,107]}})}\r\n  doc.save(\"raport-prospectare-\"+today()+\".pdf\");toast(\"Raport PDF descărcat.\")}\r\n\r\n/* ============ CALENDAR DE LUCRU ============ */\r\nlet calRef=new Date();\r\nfunction renderCal(){const y=calRef.getFullYear(),m=calRef.getMonth();\r\n  const start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();\r\n  const ev={};\r\n  tasks.forEach(t=>{if(t.scadenta){(ev[t.scadenta]=ev[t.scadenta]||[]).push({t:\"task\",l:t.titlu+(t.catre?\" (\"+t.catre+\")\":\"\")})}});\r\n  data.forEach(c=>{if(c.followupAt){const d=new Date(c.followupAt).toISOString().slice(0,10);(ev[d]=ev[d]||[]).push({t:\"call\",l:\"☎ \"+c.nume,id:c.id})}\r\n    if(c.nextAsk){(ev[c.nextAsk]=ev[c.nextAsk]||[]).push({t:\"renew\",l:\"↻ \"+c.nume,id:c.id})}\r\n    if(c.nextMoveDate){(ev[c.nextMoveDate]=ev[c.nextMoveDate]||[]).push({t:\"move\",l:\"◆ \"+(c.nextMove||c.nume),id:c.id})}\r\n    // notițe pe calendar: din update-uri recente (c.notite) + istoric (activitati tip nota); data = zi aleasă sau ziua scrierii\r\n    const notes=(c.notite||[]).concat((c.activitati||[]).filter(a=>a&&a.tip===\"nota\"));\r\n    notes.forEach(n=>{const d=n.zi||new Date(n.ts).toISOString().slice(0,10);(ev[d]=ev[d]||[]).push({t:\"note\",l:\"📝 \"+c.nume,id:c.id,title:(\"📝 \"+c.nume+\": \"+(\"\"+n.text).replace(/^📝\\s*/,\"\"))})});});\r\n  const dow=[\"L\",\"Ma\",\"Mi\",\"J\",\"V\",\"S\",\"D\"],todayStr=new Date().toISOString().slice(0,10);\r\n  let cells=dow.map(d=>`<div class=\"cdow\">${d}</div>`).join(\"\");\r\n  for(let i=0;i<start;i++)cells+='<div class=\"ccell empty\"></div>';\r\n  for(let d=1;d<=days;d++){const ds=`${y}-${String(m+1).padStart(2,\"0\")}-${String(d).padStart(2,\"0\")}`,list=ev[ds]||[];\r\n    cells+=`<div class=\"ccell clickable ${ds===todayStr?'today':''}\" onclick=\"openNoteModal('${ds}')\"><div class=\"cnum\">${d}<span class=\"cadd\" onclick=\"event.stopPropagation();openNoteModal('${ds}')\" title=\"Adaugă notiță pe ${ds}\">＋</span></div>${list.slice(0,4).map(e=>`<div class=\"cev ${e.t}\" ${e.id?`onclick=\"event.stopPropagation();gotoCo('${e.id}')\"`:''} title=\"${esc(e.title||e.l)}\">${esc(e.l)}</div>`).join(\"\")}${list.length>4?`<div class=\"cmore\">+${list.length-4}</div>`:''}</div>`}\r\n  document.getElementById(\"calPage\").innerHTML=`<h1>Calendar de lucru</h1><p class=\"lead\">Reveniri telefonice (48h), sarcini și notițe, pe zile. <b>Apasă pe orice zi</b> ca să adaugi o notiță. Sincronizat cu echipa.</p>\r\n    <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:12px\"><button class=\"tbtn sm\" onclick=\"calNav(-1)\">←</button><b style=\"font-family:'Space Grotesk';text-transform:capitalize;min-width:150px;text-align:center\">${calRef.toLocaleDateString(\"ro-RO\",{month:\"long\",year:\"numeric\"})}</b><button class=\"tbtn sm\" onclick=\"calNav(1)\">→</button><button class=\"tbtn sm\" onclick=\"calRef=new Date();renderCal()\">Azi</button>\r\n    <span style=\"margin-left:auto;font-size:11px;color:var(--muted)\"><span class=\"cev call\" style=\"display:inline-block;padding:1px 6px\">☎ revenire</span> <span class=\"cev task\" style=\"display:inline-block;padding:1px 6px\">sarcină</span> <span class=\"cev note\" style=\"display:inline-block;padding:1px 6px\">📝 notiță</span></span></div>\r\n    <div class=\"calgrid\">${cells}</div>`;\r\n}\r\nfunction calNav(d){calRef=new Date(calRef.getFullYear(),calRef.getMonth()+d,1);renderCal()}\r\n/* Notiță adăugată direct din calendar: alegi firma (din cele încărcate) + text + ziua. Notița intră la firmă și apare pe calendar. */\r\nfunction openNoteModal(dateStr,coId){if(!canEdit()){toast(\"Editare permisă doar echipei.\");return}\r\n  const sel=data.find(x=>x.id===(coId||selectedId));\r\n  const opts=data.slice().sort((a,b)=>(a.nume||\"\").localeCompare(b.nume||\"\",\"ro\")).slice(0,4000).map(c=>`<option value=\"${esc(c.nume)}\">`).join(\"\");\r\n  document.getElementById(\"noteModal\").innerHTML=`<div style=\"display:flex;justify-content:space-between;align-items:center\"><h3>Notiță pe calendar</h3><button class=\"minibtn\" onclick=\"closeOv('noteOverlay')\">✕</button></div>\r\n   <div class=\"fld\"><label>Firmă</label><input id=\"nmCo\" list=\"nmCoList\" value=\"${esc(sel?sel.nume:'')}\" placeholder=\"Scrie numele firmei…\" autocomplete=\"off\"><datalist id=\"nmCoList\">${opts}</datalist></div>\r\n   <div class=\"fld\"><label>Notiță</label><textarea id=\"nmT\" rows=\"3\" placeholder=\"Scrie update-ul…\" style=\"width:100%;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit\"></textarea></div>\r\n   <div class=\"fld\"><label>Pe ziua</label><input id=\"nmD\" type=\"date\" value=\"${esc(dateStr||new Date().toISOString().slice(0,10))}\"></div>\r\n   <div class=\"row\"><button class=\"tbtn\" onclick=\"closeOv('noteOverlay')\">Anulează</button><button class=\"tbtn primary\" onclick=\"saveNoteCal()\">Adaugă notița</button></div>`;\r\n  document.getElementById(\"noteOverlay\").classList.add(\"on\");\r\n  setTimeout(()=>{const t=document.getElementById(\"nmT\");if(t)t.focus();},60);}\r\nfunction saveNoteCal(){if(!canEdit())return;\r\n  const nm=(document.getElementById(\"nmCo\").value||\"\").trim();\r\n  const t=(document.getElementById(\"nmT\").value||\"\").trim();\r\n  const zi=(document.getElementById(\"nmD\").value||\"\")||new Date().toISOString().slice(0,10);\r\n  if(!t){toast(\"Scrie notița.\");return}\r\n  if(!nm){toast(\"Alege firma pentru notiță.\");return}\r\n  const c=data.find(x=>(x.nume||\"\").toLowerCase()===nm.toLowerCase())||data.find(x=>(x.nume||\"\").toLowerCase().indexOf(nm.toLowerCase())>=0);\r\n  if(!c){toast(\"Firma nu e în lista încărcată — caut-o întâi în Companii.\");return}\r\n  c.notite=c.notite||[];c.notite.push({ts:Date.now(),text:t,de:config.eu||\"\",zi:zi});\r\n  pushCompany(c);closeOv(\"noteOverlay\");renderCal();if(selectedId===c.id)renderDetail();\r\n  toast(\"Notiță adăugată la \"+c.nume+\" · \"+zi);}\r\nfunction openTaskModal(){document.getElementById(\"taskModal\").innerHTML=`<div style=\"display:flex;justify-content:space-between;align-items:center\"><h3>Sarcină nouă</h3><button class=\"minibtn\" onclick=\"closeOv('taskOverlay')\">✕</button></div>\r\n  <div class=\"fld\"><label>Titlu</label><input id=\"tkT\" placeholder=\"ex. Sună CFO-ul\"></div>\r\n  <div class=\"fld\"><label>Companie</label><input id=\"tkC\" value=\"${esc((data.find(x=>x.id===selectedId)||{}).nume||'')}\"></div>\r\n  <div class=\"fld\"><label>Către</label><select id=\"tkW\">${[\"\",...ECHIPA].map(r=>`<option ${config.eu===r?\"selected\":\"\"}>${r||\"—\"}</option>`).join(\"\")}</select></div>\r\n  <div class=\"fld\"><label>Scadență</label><input id=\"tkD\" type=\"date\"></div>\r\n  <div class=\"fld\"><label>Interval orar (opțional) — apasă și alegi ora</label><div style=\"display:flex;align-items:center;gap:8px\"><input id=\"tkOra1\" type=\"time\" style=\"flex:1;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit\"><span style=\"color:var(--muted)\">–</span><input id=\"tkOra2\" type=\"time\" style=\"flex:1;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit\"></div></div>\r\n  <div class=\"row\"><button class=\"tbtn\" onclick=\"closeOv('taskOverlay')\">Anulează</button><button class=\"tbtn primary\" onclick=\"saveTask()\">Adaugă</button></div>`;document.getElementById(\"taskOverlay\").classList.add(\"on\")}\r\nfunction saveTask(){if(!canEdit())return;const o1=(document.getElementById(\"tkOra1\").value||\"\"),o2=(document.getElementById(\"tkOra2\").value||\"\");const ora=o1?(o2?o1+\"-\"+o2:o1):\"\";addTask({titlu:document.getElementById(\"tkT\").value.trim(),companie:document.getElementById(\"tkC\").value.trim(),catre:document.getElementById(\"tkW\").value,scadenta:document.getElementById(\"tkD\").value,ora:ora});closeOv(\"taskOverlay\")}\r\nfunction addTask(t){if(!t.titlu)return;const nt=Object.assign({id:\"t\"+Date.now()+Math.random().toString(36).slice(2,6),gata:false,creatDe:config.eu,creatCand:Date.now()},t);tasks.push(nt);pushTasks();fsSaveTask(nt);if(curView===\"sarcini\")renderTasks();if(nt.catre&&nt.catre!==config.eu)toast(\"Sarcină alocată către \"+nt.catre)}\r\nfunction toggleTask(id){if(!canEdit())return;const t=tasks.find(x=>x.id===id);t.gata=!t.gata;pushTasks();fsSaveTask(t);renderTasks()}\r\nfunction delTask(id){if(!canEdit())return;tasks=tasks.filter(x=>x.id!==id);pushTasks();fsDelTask(id);renderTasks()}\r\n\r\n/* ============ IMPORT (orice format) ============ */\r\nconst COLMAP={nume:[\"nume\",\"companie\",\"denumire\",\"firma\",\"firmă\",\"company\",\"name\",\"societate\"],cui:[\"cui\",\"cif\",\"cod fiscal\",\"codfiscal\",\"vat\"],judet:[\"judet\",\"județ\",\"county\"],caen:[\"caen\",\"cod caen\"],nrRegCom:[\"nr reg com\",\"registrul comertului\",\"reg com\",\"nrinmatriculare\",\"numar inmatriculare\",\"inmatriculare\"],localitate:[\"localitate\",\"oras\",\"oraș\",\"city\"],adresa:[\"adresa\",\"adresă\",\"address\",\"sediu\"],site:[\"site\",\"website\",\"web\",\"url\"],ca:[\"cifra de afaceri\",\"cifra afaceri\",\"ca\",\"turnover\"],profit:[\"profit\",\"profit net\",\"profit brut\"],nrAngajati:[\"angajati\",\"angajați\",\"salariati\",\"salariați\",\"employees\",\"nr angajati\",\"numar angajati\"],email:[\"email\",\"e-mail\",\"mail\"],telefon:[\"telefon\",\"phone\",\"tel\",\"mobil\"],linkedin:[\"linkedin\"],facebook:[\"facebook\",\"fb\"],industrie:[\"industrie\",\"domeniu\",\"sector\"]};\r\nfunction norm(s){return String(s||\"\").toLowerCase().trim().replace(/[_\\-\\.]/g,\" \").replace(/\\s+/g,\" \")}\r\nfunction mapKey(header){const h=norm(header);for(const k in COLMAP)if(COLMAP[k].some(a=>h===a||h.includes(a)))return k;return null}\r\nlet importMode=\"companii\";\r\nfunction setImportMode(m){importMode=m;document.getElementById(\"imC\").classList.toggle(\"on\",m===\"companii\");document.getElementById(\"imD\").classList.toggle(\"on\",m===\"donatori\");document.getElementById(\"importHint\").textContent=m===\"donatori\"?\"Lista voastră de sponsori: coloane firmă / sumă / dată. Fiecare rând = o donație; le grupăm pe firmă (nr. donații + sumă totală) și le marcăm LEAD CALD. Apoi poți adăuga contacte manual pe fiecare firmă.\":\"Excel, CSV, TSV, ODS, PDF, Word, JSON, HTML, text. Coloane: nume, CUI, județ, CAEN, site, CA, profit, angajați, email, telefon.\"}\r\nfunction blankCo(id,nume){return {id,nume,cui:null,judet:\"\",caen:\"\",nrRegCom:\"\",localitate:\"\",adresa:\"\",anInfiintare:null,industrie:\"\",site:null,facebook:null,linkedin:null,ca:null,profit:null,profitTip:\"net\",suma:null,impozit:null,sursaFin:\"\",nrAngajati:null,status:\"nou\",responsabil:\"\",recurent:false,frecventa:\"\",priorGivingNoi:false,sumaSponsorizata:null,sumaPropusa:null,cazAsociat:\"\",abordarePrin:\"\",stilAbordare:\"\",campanie230:false,donationCount:0,donationTotal:0,trimestre:{q1:0,q2:0,q3:0,q4:0},istoric:[],ong:[],media:[],financiar3ani:[],followupAt:null,contract:null,contracte:[],nota:\"\",temp:\"\",d177:false,mec20:false,decembrie:false,administrator:\"\",activitati:[],nextAsk:null,majorGift:false,nextMove:\"\",nextMoveDate:null,contribTrecut:\"\",contacte:[]}}\r\nconst FIRMKEY=[\"firma\",\"firmă\",\"companie\",\"nume\",\"denumire\",\"sponsor\",\"donator\",\"beneficiar\",\"societate\",\"company\"],SUMKEY=[\"suma\",\"sumă\",\"valoare\",\"amount\",\"donatie\",\"donație\",\"suma sponsorizata\",\"total\"],DATEKEY=[\"data\",\"dată\",\"date\",\"perioada\",\"an\"];\r\nfunction pickCol(r,keys){for(const k in r){const h=norm(k);if(keys.some(a=>h===a||h.includes(a)))return r[k]}return null}\r\nfunction rowsToDonatori(rows){const map={};\r\n  rows.forEach(r=>{const nume=(pickCol(r,FIRMKEY)||\"\").toString().trim();if(!nume||nume.length<2)return;\r\n    const sumRaw=(pickCol(r,SUMKEY)||\"\").toString().replace(/[^\\d.,]/g,\"\").replace(/\\.(?=\\d{3}(\\D|$))/g,\"\").replace(\",\",\".\");const suma=parseFloat(sumRaw)||0;\r\n    const dt=(pickCol(r,DATEKEY)||\"\").toString().trim(),key=normName(nume);\r\n    const g=map[key]=map[key]||{nume,count:0,total:0,dates:[]};g.count++;g.total+=suma;if(dt)g.dates.push(dt)});\r\n  const keys=Object.keys(map);let added=0;const updates={};\r\n  keys.forEach((k,idx)=>{const g=map[k],dates=g.dates.slice().sort();const ex=data.find(x=>normName(x.nume)===k);\r\n    if(ex){ex.priorGivingNoi=true;ex.donationCount=(ex.donationCount||0)+g.count;ex.donationTotal=(ex.donationTotal||0)+g.total;ex.recurent=ex.donationCount>1;if(dates.length){ex.lastDonation=dates[dates.length-1];ex.firstDonation=ex.firstDonation||dates[0]}ex.updatedAt=Date.now();updates[ex.id]=ex}\r\n    else{const id=\"don-\"+k.replace(/[^a-z0-9]/g,\"\").slice(0,20)+\"-\"+idx,co=blankCo(id,g.nume);co.priorGivingNoi=true;co.donationCount=g.count;co.donationTotal=g.total;co.recurent=g.count>1;co.sursaFin=\"istoric donatori\";if(dates.length){co.firstDonation=dates[0];co.lastDonation=dates[dates.length-1]}co.updatedAt=Date.now();data.push(co);updates[id]=co;added++}});\r\n  saveLocal();if(db)db.child(\"companii\").update(updates);if(!selectedId&&data[0])selectedId=data[0].id;renderAll();toast(\"Import donatori: \"+keys.length+\" firme (\"+added+\" noi).\");closeOv(\"importOverlay\")}\r\nfunction rowsToCompanii(rows){if(importMode===\"donatori\")return rowsToDonatori(rows);let added=0,merged=0;rows.forEach((r,idx)=>{const obj={};let hasName=false;\r\n  for(const key in r){const mk=mapKey(key);if(mk){let v=r[key];if([\"ca\",\"profit\",\"nrAngajati\"].includes(mk))v=(\"\"+v).replace(/[^\\d]/g,\"\")?+((\"\"+v).replace(/[^\\d]/g,\"\")):null;obj[mk]=v;if(mk===\"nume\"&&v)hasName=true}}\r\n  if(!hasName){const first=Object.values(r)[0];if(first&&(\"\"+first).length>1){obj.nume=(\"\"+first).trim();hasName=true}}\r\n  if(!hasName)return;\r\n  const id=(obj.cui||obj.nume).toString().toLowerCase().replace(/[^a-z0-9]/g,\"\").slice(0,24)+\"-\"+idx;\r\n  const contacte=[];if(obj.email||obj.telefon)contacte.push({nume:obj.nume+\" (contact)\",rol:\"\",dept:\"\",loc:\"\",linkedin:obj.linkedin||null,email:obj.email||null,telefon:obj.telefon||null,detalii:\"\",cheie:false});\r\n  const co={id,nume:obj.nume,cui:obj.cui||null,judet:obj.judet||\"\",caen:obj.caen||\"\",nrRegCom:obj.nrRegCom||\"\",localitate:obj.localitate||\"\",adresa:obj.adresa||\"\",anInfiintare:null,industrie:obj.industrie||\"\",site:obj.site||null,facebook:obj.facebook||null,linkedin:null,ca:obj.ca||null,profit:obj.profit||null,profitTip:\"net\",suma:null,sursaFin:\"import\",nrAngajati:obj.nrAngajati||null,status:\"nou\",responsabil:\"\",recurent:false,frecventa:\"\",priorGivingNoi:false,sumaSponsorizata:null,sumaPropusa:null,cazAsociat:\"\",abordarePrin:\"\",stilAbordare:\"\",campanie230:false,trimestre:{q1:0,q2:0,q3:0,q4:0},istoric:[],ong:[],media:[],financiar3ani:[],followupAt:null,contract:null,nota:\"\",administrator:\"\",contacte};\r\n  const ex=data.find(x=>(co.cui&&x.cui===co.cui)||normName(x.nume)===normName(co.nume));\r\n  if(ex){[\"cui\",\"judet\",\"caen\",\"nrRegCom\",\"localitate\",\"adresa\",\"site\",\"ca\",\"profit\",\"nrAngajati\",\"industrie\"].forEach(k=>{if(!ex[k]&&co[k])ex[k]=co[k]});pushCompany(ex);merged++}\r\n  else{data.push(co);pushCompany(co);added++}});\r\n  saveLocal();renderAll();toast(\"Import: \"+added+\" noi, \"+merged+\" actualizate/unite.\");closeOv(\"importOverlay\")}\r\nfunction parseText(txt){const lines=txt.split(/\\r?\\n/).map(l=>l.trim()).filter(l=>l.length>1);if(!lines.length)return[];\r\n  const sep=lines[0].includes(\"\\t\")?\"\\t\":lines[0].includes(\";\")?\";\":lines[0].includes(\",\")?\",\":null;\r\n  if(sep){const head=lines[0].split(sep).map(s=>s.trim());return lines.slice(1).map(l=>{const cells=l.split(sep);const o={};head.forEach((h,i)=>o[h]=(cells[i]||\"\").trim());return o})}\r\n  return lines.map(l=>({nume:l}))}\r\nfunction handleFiles(files){const f=files[0];if(!f)return;const ext=f.name.split(\".\").pop().toLowerCase();\r\n  if([\"xlsx\",\"xls\",\"xlsm\",\"ods\",\"csv\",\"tsv\"].includes(ext)){const rd=new FileReader();rd.onload=e=>{try{const wb=XLSX.read(e.target.result,{type:\"binary\"});const rows=[];wb.SheetNames.forEach(n=>XLSX.utils.sheet_to_json(wb.Sheets[n],{defval:\"\"}).forEach(r=>rows.push(r)));rowsToCompanii(rows)}catch(err){toast(\"Eroare la citire.\")}};rd.readAsBinaryString(f)}\r\n  else if(ext===\"json\"){const rd=new FileReader();rd.onload=e=>{try{const arr=JSON.parse(e.target.result);rowsToCompanii(Array.isArray(arr)?arr:[arr])}catch(err){toast(\"JSON invalid.\")}};rd.readAsText(f)}\r\n  else if(ext===\"docx\"){const rd=new FileReader();rd.onload=e=>mammoth.extractRawText({arrayBuffer:e.target.result}).then(r=>rowsToCompanii(parseText(r.value))).catch(()=>toast(\"Eroare docx.\"));rd.readAsArrayBuffer(f)}\r\n  else if(ext===\"pdf\"){const rd=new FileReader();rd.onload=e=>{pdfjsLib.GlobalWorkerOptions.workerSrc=\"https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js\";pdfjsLib.getDocument({data:e.target.result}).promise.then(async pdf=>{let txt=\"\";for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i);const tc=await pg.getTextContent();const byY={};tc.items.forEach(it=>{const y=Math.round(it.transform[5]);(byY[y]=byY[y]||[]).push(it.str)});Object.keys(byY).sort((a,b)=>b-a).forEach(y=>txt+=byY[y].join(\" \")+\"\\n\")}rowsToCompanii(parseText(txt))}).catch(()=>toast(\"Eroare pdf.\"))};rd.readAsArrayBuffer(f)}\r\n  else if([\"html\",\"htm\"].includes(ext)){const rd=new FileReader();rd.onload=e=>{const doc=new DOMParser().parseFromString(e.target.result,\"text/html\");const tbl=doc.querySelector(\"table\");if(tbl){const rows=[...tbl.querySelectorAll(\"tr\")].map(tr=>[...tr.children].map(td=>td.textContent.trim()));const head=rows[0];rowsToCompanii(rows.slice(1).map(r=>{const o={};head.forEach((h,i)=>o[h]=r[i]||\"\");return o}))}else rowsToCompanii(parseText(doc.body.textContent))};rd.readAsText(f)}\r\n  else{const rd=new FileReader();rd.onload=e=>rowsToCompanii(parseText(e.target.result));rd.readAsText(f)}\r\n}\r\nfunction openImport(){document.getElementById(\"importText\").value=\"\";document.getElementById(\"importOverlay\").classList.add(\"on\")}\r\nlet addCoDinAnaf=false;\r\nfunction openAddCo(){if(!canEdit())return;addCoDinAnaf=false;[\"acCui\",\"acNume\",\"acJudet\",\"acLoc\",\"acAdr\",\"acCaen\",\"acReg\",\"acAng\",\"acInf\",\"acCA\",\"acProfit\"].forEach(id=>{const el=document.getElementById(id);if(el)el.value=\"\"});document.getElementById(\"addOverlay\").classList.add(\"on\")}\r\nfunction saveAddCo(){if(!canEdit())return;const g=id=>document.getElementById(id).value.trim();const nume=g(\"acNume\"),cui=g(\"acCui\");if(!nume&&!cui){toast(\"Pune cel puțin numele sau CUI-ul.\");return}\r\n  const id=(window.crypto&&crypto.randomUUID)?crypto.randomUUID():((cui||nume).toLowerCase().replace(/[^a-z0-9]/g,\"\").slice(0,24)+\"-\"+Date.now().toString(36));\r\n  const co=blankCo(id,nume||cui);co.cui=cui||null;co.judet=g(\"acJudet\");co.localitate=g(\"acLoc\");co.adresa=g(\"acAdr\");co.caen=g(\"acCaen\");co.nrRegCom=g(\"acReg\");\r\n  co.nrAngajati=+g(\"acAng\")||null;co.anInfiintare=+g(\"acInf\")||null;co.ca=+g(\"acCA\")||null;co.profit=+g(\"acProfit\")||null;co.profitTip=\"net\";co.sursaFin=addCoDinAnaf?\"bilanț (ANAF/cuiscan)\":\"manual\";\r\n  if(co.ca&&co.profit){co.impozit=Math.round(co.profit*0.16);recompSuma(co)}\r\n  data.push(co);selectedId=id;pushCompany(co);closeOv(\"addOverlay\");document.body.classList.add(\"showing-detail\");renderList();toast(\"Firmă adăugată.\")}\r\nasync function anafPull(){const cui=(document.getElementById(\"acCui\").value||\"\").replace(/\\D/g,\"\");if(!cui){toast(\"Scrie CUI-ul întâi.\");return}\r\n  const btn=event&&event.target;if(btn){btn.disabled=true;btn.textContent=\"…\"}\r\n  toast(\"Caut la ANAF/cuiscan…\");\r\n  const set=(id,v)=>{const el=document.getElementById(id);if(el&&v!=null&&v!==\"\"&&v!==0)el.value=v};\r\n  let ok=false;\r\n  try{\r\n    try{const rc=await fetch(API_BASE+\"/crm-anaf?action=company&cui=\"+cui);let co=await rc.json().catch(()=>null);if(co&&co.data)co=co.data;if(co){set(\"acNume\",co.denumire||co.nume||co.name);set(\"acJudet\",co.judet||co.judetName||co.county);set(\"acLoc\",co.localitate||co.oras||co.city);set(\"acAdr\",co.adresa||co.strada||co.address);set(\"acCaen\",co.codCaen||co.caen||co.cod_caen);set(\"acReg\",co.nrRegCom||co.regcom||co.numarRegistruComert);ok=true}}catch(e){}\r\n    try{const rf=await fetch(API_BASE+\"/crm-anaf?action=financials&cui=\"+cui);let fin=await rf.json().catch(()=>null);if(fin&&fin.data)fin=fin.data;const f=Array.isArray(fin)?fin[0]:fin;if(f){set(\"acCA\",Math.round(f.cifraAfaceri||f.ca||f.cifra_afaceri||0));set(\"acProfit\",Math.round(f.profitNet||f.profit_net||f.profit||0));set(\"acAng\",f.nrAngajati||f.numarSalariati||f.salariati);set(\"acInf\",f.an&&!document.getElementById(\"acInf\").value?\"\":document.getElementById(\"acInf\").value);ok=true}}catch(e){}\r\n    if(ok){addCoDinAnaf=true;toast(\"Completat din ANAF/cuiscan. Verifică numele și apasă „Adaugă firma”.\");}\r\n    else toast(\"Nu am găsit date pentru acest CUI. Completează manual.\");\r\n  }catch(e){toast(\"cuiscan indisponibil — completează manual. (\"+e.message+\")\")}\r\n  if(btn){btn.disabled=false;btn.textContent=\"↻ ANAF\"}\r\n}\r\nlet contacteCandidates=[],contacteForId=null,contactePoll=null;\r\nfunction renderContactHelper(c){\r\n  const nume=encodeURIComponent(c.nume||\"\");\r\n  const spons='CEO OR Founder OR Owner OR \"Managing Director\" OR \"General Manager\" OR CFO OR \"Finance Director\" OR \"Head of Finance\" OR \"CSR Manager\" OR \"ESG Manager\" OR \"Sustainability Manager\" OR \"Corporate Affairs Manager\"';\r\n  const f230='\"HR Director\" OR \"Head of HR\" OR \"HR Manager\" OR \"HR Business Partner\" OR \"Chief People Officer\" OR \"People & Culture Manager\" OR \"Internal Communications Manager\" OR \"Employee Engagement Manager\" OR \"Employer Branding Manager\"';\r\n  const cbtn=(txt,label)=>`<button class=\"tbtn sm\" onclick='navigator.clipboard.writeText(${JSON.stringify(txt)}).then(()=>toast(\"Copiat!\"))'>⧉ ${label}</button>`;\r\n  document.getElementById(\"contacteList\").innerHTML=`\r\n    <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 14px\">\r\n      <a class=\"tbtn sm\" target=\"_blank\" rel=\"noopener\" href=\"https://www.linkedin.com/search/results/people/?keywords=${nume}\">🔗 LinkedIn</a>\r\n      <a class=\"tbtn sm\" target=\"_blank\" rel=\"noopener\" href=\"https://app.apollo.io/#/people?qKeywords=${nume}\">🔗 Apollo</a>\r\n      <a class=\"tbtn sm\" target=\"_blank\" rel=\"noopener\" href=\"https://dashboard.lusha.com/prospecting\">🔗 Lusha</a></div>\r\n    <div style=\"border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:10px\">\r\n      <b>Sponsorizare (D177 / 20%)</b> — conducere, financiar, CSR/ESG\r\n      <div style=\"font-size:11px;background:#f6f7f9;border-radius:8px;padding:8px;margin:6px 0;white-space:pre-wrap;font-family:monospace\">${esc(spons)}</div>${cbtn(spons,\"Copiază pentru Apollo\")}</div>\r\n    <div style=\"border:1px solid var(--line);border-radius:10px;padding:12px\">\r\n      <b>Formularul 230</b> — HR, comunicare internă, engagement\r\n      <div style=\"font-size:11px;background:#f6f7f9;border-radius:8px;padding:8px;margin:6px 0;white-space:pre-wrap;font-family:monospace\">${esc(f230)}</div>${cbtn(f230,\"Copiază pentru Apollo\")}</div>\r\n    <p class=\"loc\" style=\"margin-top:10px\">Adaugă contactele găsite cu butonul „+ Contact” de pe fișă.</p>`;\r\n}\r\nasync function fsGetCandidate(){return null;}\r\nasync function clearFsCandidate(){}\r\n\r\nfunction contactLinks(c){const n=encodeURIComponent(c.nume||\"\");return '<div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:8px\"><a class=\"tbtn sm\" target=\"_blank\" rel=\"noopener\" href=\"https://www.linkedin.com/search/results/people/?keywords='+n+'\">🔗 LinkedIn</a><a class=\"tbtn sm\" target=\"_blank\" rel=\"noopener\" href=\"https://app.apollo.io/#/people?qKeywords='+n+'\">🔗 Apollo</a><a class=\"tbtn sm\" target=\"_blank\" rel=\"noopener\" href=\"https://dashboard.lusha.com/prospecting\">🔗 Lusha</a></div>'}\r\nasync function openContacte(id){if(!canEdit())return;contacteForId=id;const c=data.find(x=>x.id===id);if(!c)return;\r\n  contacteCandidates=[];document.getElementById(\"contacteList\").innerHTML=\"\";\r\n  const act=document.getElementById(\"contacteActions\");if(act)act.style.display=\"none\";\r\n  const st=document.getElementById(\"contacteStatus\");\r\n  document.getElementById(\"contacteOverlay\").classList.add(\"on\");\r\n  if(contactePoll){clearInterval(contactePoll);contactePoll=null}\r\n  if(!config.makeWebhook){if(st)st.innerHTML=\"Lipsește webhook-ul Make (⚙ Setări). \"+contactLinks(c);return}\r\n  if(st)st.innerHTML='Caut automat decidenți prin <b>Apollo &amp; Lusha</b> (consumă credite)… <span id=\"ctTimer\">~120s</span>';\r\n  await clearFsCandidate(c.id);\r\n  postMake(\"contacte\",{id:c.id,cui:c.cui,nume:c.nume,domeniu:(c.site||\"\").replace(/^https?:\\/\\//,\"\").replace(/\\/.*$/,\"\")});\r\n  let n=0;const MAX=40;\r\n  contactePoll=setInterval(async()=>{n++;const rem=(MAX-n)*3;\r\n    const cand=await fsGetCandidate(contacteForId);\r\n    if(cand){const clean=cand.map(p=>Object.assign({},p,{dept:p.dept||deptFromRol(p.rol)})).filter(p=>p.nume&&(\"\"+p.nume).trim()&&(\"\"+p.nume).trim()!==\"undefined undefined\");\r\n      if(clean.length){clearInterval(contactePoll);contactePoll=null;const cc=data.find(x=>x.id===contacteForId);if(cc)cc.candidate=clean;showCandidates(clean);return}}\r\n    const t=document.getElementById(\"ctTimer\");if(t)t.textContent=\"~\"+Math.max(rem,0)+\"s\";\r\n    if(n>=MAX){clearInterval(contactePoll);contactePoll=null;if(st)st.innerHTML='Nu s-au întors persoane automat (verifică creditele Apollo/Lusha) — sau caută manual: '+contactLinks(c)}\r\n  },3000);\r\n}\r\nasync function tryConnectors(c){\r\n  const dom=(c.site||\"\").replace(/^https?:\\/\\//,\"\").replace(/\\/.*$/,\"\");\r\n  const q='Caută factorii de decizie de la firma \"'+c.nume+'\" din România'+(c.cui?(\", CUI \"+c.cui):\"\")+(dom?(\", domeniu \"+dom):\"\")+'. Folosește Lusha și Apollo și returnează DOAR persoane care au una dintre aceste funcții (sau echivalentul lor evident): '\r\n    +'CEO, Chief Executive Officer, Founder, Co-Founder, Owner, Business Owner, Managing Director, General Manager, Country Manager, Managing Partner, Administrator, '\r\n    +'CFO, Chief Financial Officer, Finance Director, Financial Director, Head of Finance, Finance Manager, Chief Accountant, Accounting Manager, Economic Director, Tax Manager, '\r\n    +'CSR Manager, ESG Manager, Head of ESG, Sustainability Manager, Head of Sustainability, Social Impact Manager, Corporate Affairs Manager, Public Affairs Manager, Foundation Manager, '\r\n    +'HR Director, Human Resources Director, Head of HR, HR Manager, HR Business Partner, Chief People Officer, People Director, People & Culture Manager, Head of People, '\r\n    +'Internal Communications Manager, Employee Communications Manager, Employee Engagement Manager, Employee Experience Manager, Employer Branding Manager. '\r\n    +'Ignoră orice persoană care NU are una dintre aceste funcții. Răspunde DOAR cu un array JSON (fără alt text), fiecare element {\"nume\":\"\",\"rol\":\"\",\"dept\":\"\",\"linkedin\":\"\",\"email\":\"\",\"telefon\":\"\"}, unde dept este unul dintre \"Conducere\",\"Financiar\",\"CSR\",\"HR\" în funcție de rol.';\r\n  try{\r\n    const res=await fetch(\"https://api.anthropic.com/v1/messages\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({model:\"claude-sonnet-4-6\",max_tokens:1500,messages:[{role:\"user\",content:q}],mcp_servers:[{type:\"url\",url:\"https://mcp.lusha.com/mcp/claude\",name:\"lusha\"},{type:\"url\",url:\"https://mcp.apollo.io/mcp\",name:\"apollo\"}]})});\r\n    const rj=await res.json();const text=(rj.content||[]).filter(b=>b.type===\"text\").map(b=>b.text).join(\"\\n\");\r\n    const a=text.indexOf(\"[\"),b=text.lastIndexOf(\"]\");if(a>=0&&b>a)return (JSON.parse(text.slice(a,b+1))||[]).filter(x=>x&&x.nume);\r\n  }catch(e){}\r\n  return [];\r\n}\r\nfunction showCandidates(arr){\r\n  contacteCandidates=(arr||[]).filter(x=>x&&x.nume&&(\"\"+x.nume).trim());contacteCandidates.forEach(p=>p._sel=true);\r\n  if(!contacteCandidates.length){document.getElementById(\"contacteStatus\").textContent=\"Nu am găsit contacte pentru firma asta.\";return}\r\n  document.getElementById(\"contacteStatus\").textContent=\"Am găsit \"+contacteCandidates.length+\" contacte. Bifează ce vrei să adaugi, apoi Aprobă:\";\r\n  document.getElementById(\"contacteList\").innerHTML=contacteCandidates.map((p,i)=>`<label style=\"display:flex;gap:8px;align-items:flex-start;padding:7px 0;border-bottom:1px solid var(--line-soft)\"><input type=\"checkbox\" checked onchange=\"contacteCandidates[${i}]._sel=this.checked\"><div><b>${esc(p.nume)}</b> — ${esc(p.rol||\"\")}<div class=\"loc\">${esc(p.dept||\"\")}${p.linkedin?' · LinkedIn':''}${p.email?' · '+esc(p.email):''}${p.telefon?' · '+esc(p.telefon):''}${p.sursa?' · '+esc(p.sursa):''}</div></div></label>`).join(\"\");\r\n  document.getElementById(\"contacteActions\").style.display=\"flex\";\r\n}\r\nfunction approveContacte(){if(!canEdit())return;const c=data.find(x=>x.id===contacteForId);if(!c)return;const sel=contacteCandidates.filter(p=>p._sel!==false);if(!sel.length){toast(\"Nu ai bifat niciun contact.\");return}sel.forEach(p=>{c.contacte.push({nume:(\"\"+p.nume).trim(),rol:p.rol||\"\",dept:p.dept||\"\",loc:\"\",linkedin:p.linkedin||null,email:p.email||null,telefon:p.telefon||null,detalii:p.sursa||\"Apollo/Lusha\",consimtamant:\"?\",cheie:[\"Conducere\",\"Financiar\",\"HR\",\"Marketing\",\"General Management\"].includes(p.dept)});logAct(c,\"nota\",\"Adăugat \"+(\"\"+p.nume).trim()+\" (\"+(p.sursa||\"Apollo/Lusha\")+\")\")});c.candidate=null;pushCompany(c);closeOv(\"contacteOverlay\");renderDetail();toast(sel.length+\" contacte adăugate.\")}\r\nfunction doImportJSON(){try{const arr=JSON.parse(document.getElementById(\"importText\").value);rowsToCompanii(Array.isArray(arr)?arr:[arr])}catch(e){toast(\"JSON invalid.\")}}\r\n\r\n/* ============ EXPORT ============ */\r\nfunction flatRows(){return data.flatMap(c=>{const base={Companie:c.nume,CUI:c.cui||\"\",Judet:c.judet||\"\",Localitate:c.localitate||\"\",Adresa:c.adresa||\"\",RegCom:c.nrRegCom||\"\",CAEN:c.caen||\"\",Industrie:c.industrie||\"\",Angajati:c.nrAngajati||\"\",CifraAfaceri:c.ca||\"\",Profit:c.profit||\"\",SumaSponsorizabila:c.suma||\"\",SumaCeruta:c.sumaPropusa||\"\",SumaSponsorizata:c.sumaSponsorizata||\"\",Status:stLabel(c.status),Responsabil:c.responsabil||\"\",LeadCald:c.priorGivingNoi?\"Da\":\"Nu\",DonatiiNr:c.donationCount||\"\",DonatiiTotal:c.donationTotal||\"\",Recurent:c.recurent?\"Da\":\"Nu\",Frecventa:c.frecventa||\"\",Site:c.site||\"\",Facebook:c.facebook||\"\",Administrator:c.administrator||\"\"};\r\n  if(!c.contacte.length)return[Object.assign({},base,{Contact:\"\",Rol:\"\",Departament:\"\",LinkedIn:\"\",Email:\"\",Telefon:\"\"})];\r\n  return c.contacte.map(p=>Object.assign({},base,{Contact:p.nume,Rol:p.rol,Departament:p.dept,LinkedIn:p.linkedin||\"\",Email:p.email||\"\",Telefon:p.telefon||\"\",Consimtamant:p.consimtamant||\"\"}))})}\r\nfunction dl(name,blob){const a=document.createElement(\"a\");a.href=URL.createObjectURL(blob);a.download=name;a.click()}\r\nconst today=()=>new Date().toISOString().slice(0,10);\r\nfunction exportJSON(){if(!isAdmin()){toast(\"Export permis doar administratorilor organizației.\");return}dl(\"crm-\"+today()+\".json\",new Blob([JSON.stringify(data,null,2)],{type:\"application/json\"}));toast(\"Export JSON.\")}\r\nfunction exportCSV(){if(!isAdmin()){toast(\"Export permis doar administratorilor organizației.\");return}const r=flatRows(),h=Object.keys(r[0]||{Companie:1});const csv=[h.join(\",\")].concat(r.map(o=>h.map(k=>`\"${String(o[k]).replace(/\"/g,'\"\"')}\"`).join(\",\"))).join(\"\\n\");dl(\"crm-\"+today()+\".csv\",new Blob([\"\\ufeff\"+csv],{type:\"text/csv\"}));toast(\"Export CSV.\")}\r\nfunction exportXLSX(){if(!isAdmin()){toast(\"Export permis doar administratorilor organizației.\");return}if(typeof XLSX===\"undefined\"){toast(\"Excel indisponibil.\");return}const ws=XLSX.utils.json_to_sheet(flatRows()),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,\"Companii\");XLSX.writeFile(wb,\"crm-\"+today()+\".xlsx\");toast(\"Export Excel.\")}\r\nfunction exportRaport20k(){if(!isAdmin()){toast(\"Export permis doar administratorilor organizației.\");return}const mari=data.filter(c=>(c.sumaSponsorizata||c.suma||0)>20000).map(c=>({Companie:c.nume,Suma:c.sumaSponsorizata||c.suma,Responsabil:c.responsabil||\"\",Status:stLabel(c.status),Frecventa:c.frecventa||\"\",Recurent:c.recurent?\"Da\":\"Nu\",LeadCald:c.priorGivingNoi?\"Da\":\"Nu\"}));if(typeof XLSX===\"undefined\"){toast(\"Excel indisponibil.\");return}const ws=XLSX.utils.json_to_sheet(mari),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,\"Peste 20k\");XLSX.writeFile(wb,\"raport-20k-\"+today()+\".xlsx\");toast(\"Raport exportat.\")}\r\n\r\n/* ============ SETĂRI ============ */\r\nfunction renderEchipa(){const b=document.getElementById(\"echipaBox\");if(!b)return;b.innerHTML=ECHIPA.map(m=>`<span style=\"display:inline-flex;align-items:center;gap:6px;background:#f0faf7;color:#0E7C6B;border:1px solid #cde9e0;border-radius:99px;padding:3px 10px;font-size:13px;font-weight:600\">${esc(m)} <span onclick=\"delMembru('${esc(m)}')\" style=\"cursor:pointer;color:#c0392b\" title=\"Scoate\">✕</span></span>`).join(\"\")||'<span class=\"loc\">Niciun membru.</span>'}\r\nfunction addMembru(){const el=document.getElementById(\"echipaNou\");const n=(el.value||\"\").trim();if(!n)return;if(!ECHIPA.includes(n))ECHIPA.push(n);el.value=\"\";fsSaveTeam();renderEchipa();document.getElementById(\"setEu\").innerHTML=[\"\",...ECHIPA].map(r=>`<option ${config.eu===r?\"selected\":\"\"}>${r||\"—\"}</option>`).join(\"\");renderAll();toast(\"Membru adăugat: \"+n)}\r\nfunction delMembru(n){ECHIPA=ECHIPA.filter(x=>x!==n);fsSaveTeam();renderEchipa();document.getElementById(\"setEu\").innerHTML=[\"\",...ECHIPA].map(r=>`<option ${config.eu===r?\"selected\":\"\"}>${r||\"—\"}</option>`).join(\"\");renderAll()}\r\nasync function fsSaveTeam(){/* echipa fixa local pe platforma */}\r\nasync function fsLoadTeam(){const se=document.getElementById(\"setEu\");if(se)se.innerHTML=[\"\",...ECHIPA].map(function(x){return \"<option \"+(config.eu===x?\"selected\":\"\")+\">\"+(x||\"—\")+\"</option>\";}).join(\"\");}\r\nfunction openSetup(){document.getElementById(\"setEu\").innerHTML=[\"\",...ECHIPA].map(r=>`<option ${config.eu===r?\"selected\":\"\"}>${r||\"—\"}</option>`).join(\"\");renderEchipa();\r\n  document.getElementById(\"setWebhook\").value=config.makeWebhook||\"\";document.getElementById(\"setCalendly\").value=config.calendly||\"\";document.getElementById(\"setVlad\").value=config.calendlyVlad||\"\";document.getElementById(\"setL20\").value=config.link20||\"\";document.getElementById(\"setL230\").value=config.link230||\"\";document.getElementById(\"setSemnatura\").value=(config.semnaturi&&config.semnaturi[config.eu])||\"\";\r\n  document.getElementById(\"setOngNume\").value=config.ongNume||\"\";document.getElementById(\"setOngSediu\").value=config.ongSediu||\"\";document.getElementById(\"setOngCif\").value=config.ongCif||\"\";document.getElementById(\"setOngInreg\").value=config.ongInregistrare||\"\";document.getElementById(\"setOngIban\").value=config.ongIban||\"\";document.getElementById(\"setOngBanca\").value=config.ongBanca||\"\";document.getElementById(\"setOngRep\").value=config.ongReprezentant||\"\";document.getElementById(\"setOngFct\").value=config.ongFunctie||\"\";document.getElementById(\"setOngEmail\").value=config.ongEmail||\"\";document.getElementById(\"setOngSite\").value=config.ongSite||\"\";\r\n  document.getElementById(\"setBrandColor\").value=config.brandColor||\"#C81E4A\";\r\n  document.getElementById(\"setupOverlay\").classList.add(\"on\")}\r\nfunction saveSetup(){if(!canEdit())return;config.eu=document.getElementById(\"setEu\").value;config.semnaturi=config.semnaturi||{};if(config.eu)config.semnaturi[config.eu]=document.getElementById(\"setSemnatura\").value;config.makeWebhook=document.getElementById(\"setWebhook\").value.trim();config.calendly=document.getElementById(\"setCalendly\").value.trim();config.calendlyVlad=document.getElementById(\"setVlad\").value.trim();config.link20=document.getElementById(\"setL20\").value.trim();config.link230=document.getElementById(\"setL230\").value.trim();\r\n  config.ongNume=document.getElementById(\"setOngNume\").value.trim();config.ongSediu=document.getElementById(\"setOngSediu\").value.trim();config.ongCif=document.getElementById(\"setOngCif\").value.trim();config.ongInregistrare=document.getElementById(\"setOngInreg\").value.trim();config.ongIban=document.getElementById(\"setOngIban\").value.trim();config.ongBanca=document.getElementById(\"setOngBanca\").value.trim();config.ongReprezentant=document.getElementById(\"setOngRep\").value.trim();config.ongFunctie=document.getElementById(\"setOngFct\").value.trim();config.ongEmail=document.getElementById(\"setOngEmail\").value.trim();config.ongSite=document.getElementById(\"setOngSite\").value.trim();\r\n  config.brandColor=document.getElementById(\"setBrandColor\").value||\"#C81E4A\";\r\n  pushConfig();reflectConfig();closeOv(\"setupOverlay\");toast(\"Setări salvate.\")}\r\nfunction updateEuLabel(){const el=document.getElementById(\"euLabel\");if(!el)return;const eu=config.eu||\"\";const n=eu?data.filter(c=>(c.responsabil||\"\")===eu).length:0;el.textContent=\"Eu: \"+(eu||\"—\")+(eu?\" · \"+n+\" \"+(n===1?\"firmă\":\"firme\"):\"\")+(readOnly?\" (doar-citire)\":\"\");}\r\nfunction reflectConfig(){applyBrandColor();updateEuLabel();var eg=document.getElementById(\"exportGroup\");if(eg)eg.style.display=isAdmin()?\"flex\":\"none\";renderSegments()}\r\n\r\n/* ============ DRAG-DROP ============ */\r\nwindow.addEventListener(\"DOMContentLoaded\",()=>{const dz=document.getElementById(\"drop\");[\"dragenter\",\"dragover\"].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add(\"over\")}));[\"dragleave\",\"drop\"].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove(\"over\")}));dz.addEventListener(\"drop\",e=>handleFiles(e.dataTransfer.files))});\r\n\r\n/* ============ INIT ============ */\r\n(function(){document.getElementById(\"logoImg\").src=LOGO;\r\n  const local=lsGet(KEY);tasks=local&&local.tasks?local.tasks:[];if(local&&local.config)config=Object.assign(config,local.config);\r\n  authEnabled=false;\r\n  try{var _ln=(localStorage.getItem(\"soi-crm-loginname\")||\"\").trim();if(_ln)config.eu=(_ln.split(/\\s+/)[0]||_ln);}catch(e){}\r\n  reflectConfig();\r\n  addFsBar();fsLoadTasks();fsLoadTeam();loadContactActivity();restoreFiltersState();restoreCenteredMode();initSwipe();\r\n  fetch(API_BASE+\"/crm-kv/config\").then(r=>r.ok?r.json():null).then(cc=>{if(cc&&typeof cc===\"object\"&&Object.keys(cc).length){var _eu=config.eu;config=Object.assign(config,cc);config.eu=_eu;reflectConfig();}}).catch(()=>{});\r\n  loadOpens();try{setInterval(loadOpens,45000);}catch(e){}\r\n  const cache=loadCache();\r\n  var _hadCache=!!(cache&&cache.data&&cache.data.length);\r\n  if(cache&&cache.data&&cache.data.length){\r\n    var _byId={};cache.data.forEach(function(c){if(c&&c.id&&!_byId[c.id])_byId[c.id]=c;});data=Object.values(_byId);\r\n    // Cache „ușor\" → marchează firmele ca incomplete; detaliile se încarcă la deschidere.\r\n    if(cache.slim)data.forEach(function(c){c._slim=true;});\r\n    _seen=new Set(data.map(function(c){return c.id;}));\r\n    // La refresh: arată ultima companie lucrată în detaliu (nu ecran gol), dar NU forța\r\n    // vederea de detaliu (fără showing-detail) — pe mobil rămâi pe listă.\r\n    selectedId=cache.selectedId||(data[0]&&data[0].id);document.body.classList.remove(\"showing-detail\");fsJudet=cache.fsJudet||\"\";fsTotal=(cache.fsTotal!=null)?cache.fsTotal:null;\r\n    fsCursor=(cache.fsCursor!==undefined)?cache.fsCursor:false;\r\n    renderAll();updateFsBar();fsRefreshTotal();\r\n    // NU reîncărca automat la boot: firmele încărcate (mai ales un subset ca „Lucrate\"/\r\n    // județ, sau doar primele pagini) trebuie să rămână după refresh — altfel dispar de\r\n    // fiecare dată. Cache-ul păstrează ce ai încărcat; pentru mai multe există butoanele\r\n    // „mai multe\" / „↺ Toate\".\r\n  }\r\n  else{data=[];renderAll();}\r\n  // Deep-link „?co=<id>\": firmă deschisă în filă nouă din Top → o selectăm și o hidratăm.\r\n  var _co=null;\r\n  try{\r\n    var _s=\"\";try{_s=(window.parent&&window.parent!==window)?window.parent.location.search:location.search;}catch(e){_s=location.search;}\r\n    _co=new URLSearchParams(_s||\"\").get(\"co\");\r\n    if(_co){\r\n      if(!data.find(function(x){return x.id===_co;})){data.push({id:_co,_slim:true,nume:\"…\",contacte:[]});_seen.add(_co);}\r\n      selectedId=_co;document.body.classList.add(\"showing-detail\");renderAll();\r\n    }\r\n  }catch(e){}\r\n  // După autentificare (prima încărcare în această sesiune de tab): arată DOAR companiile tale,\r\n  // cele lucrate recent primele. La refresh (aceeași sesiune) păstrăm ce e încărcat. „?co\" are prioritate.\r\n  var _mineOnce=false;try{_mineOnce=sessionStorage.getItem(\"soi-crm-mine1\")===\"1\";}catch(e){}\r\n  var _wantMine=config.eu&&!_co&&!_mineOnce;\r\n  if(_wantMine){try{sessionStorage.setItem(\"soi-crm-mine1\",\"1\");}catch(e){}\r\n    fsLoadMine().then(function(ok){if(!ok&&!_hadCache)fsLoad(true);});\r\n  }else if(!_hadCache){fsLoad(true);}\r\n})();\r\n</script>\r\n</body>\r\n</html>\r\n";
